// config/migrate.t27 — Config Migration Specification
// Version detection, upgrade, compatibility handling
// φ² + 1/φ² = 3 | TRINITY

module config-migrate;

// ============================================================================
// Imports
// ============================================================================

use std;

// ============================================================================
// Constants
// ============================================================================

/// Current migration schema version
pub const MIGRATION_VERSION : u16 = 1;

/// Minimum supported config version
pub const MIN_SUPPORTED_VERSION : u16 = 1;

/// Maximum migration steps
pub const MAX_MIGRATION_STEPS : u8 = 10;

/// Migration timeout in seconds
pub const MIGRATION_TIMEOUT_SEC : u16 = 60;

/// Config version key
pub const VERSION_KEY : [7]u8 = "version";

/// Backup file suffix
pub const BACKUP_SUFFIX : [4]u8 = ".bak";

/// Migration result type
pub const MigrationResultType = enum(u8) {
    success = 0,
    partial = 1,     // Some migrations failed
    failed = 2,     // Migration could not complete
    skipped = 3,     // No migration needed
};

/// Migration action
pub const MigrationAction = enum(u8) {
    add_field = 0,
    remove_field = 1,
    rename_field = 2,
    change_type = 3,
    set_default = 4,
    migrate_value = 5,
};

/// Migration severity
pub const MigrationSeverity = enum(u8) {
    info = 0,
    warning = 1,
    error = 2,
    critical = 3,
};

// ============================================================================
// Types
// ============================================================================

/// Migration step
pub const MigrationStep = struct {
    from_version : u16,
    to_version : u16,
    action : MigrationAction,
    field_name : []u8,
    old_value : []u8,
    new_value : []u8,
    description : []u8,
};

/// Migration rule
pub const MigrationRule = struct {
    applies_to_version : ?u16,
    check_fn : fn(*u8) bool,
    migrate_fn : fn(*u8) MigrationAction,
    description : []u8,
};

/// Migration result
pub const MigrationResult = struct {
    result_type : MigrationResultType,
    steps : []MigrationStep,
    errors : []MigrationError,
    from_version : u16,
    to_version : u16,
    backup_path : ?[]u8,
};

/// Migration error
pub const MigrationError = struct {
    step : u8,
    field : []u8,
    message : []u8,
    severity : MigrationSeverity,
};

/// Config version info
pub const VersionInfo = struct {
    version : u16,
    schema_version : u16,
    migration_version : u16,
};

/// Migration context
pub const MigrationContext = struct {
    dry_run : bool,
    backup_enabled : bool,
    force_migration : bool,
    verbose : bool,
};

// ============================================================================
// Functions
// ============================================================================

/// Detect config version from structure
pub fn detect_version(config_data: *u8) u16 {
    // Simplified: would parse and extract version
    return MIN_SUPPORTED_VERSION;
}

/// Check if version is supported
pub fn is_version_supported(version: u16) bool {
    return version >= MIN_SUPPORTED_VERSION;
}

/// Check if migration is needed
pub fn needs_migration(current_version: u16, target_version: u16) bool {
    return current_version < target_version;
}

/// Create migration step
pub fn step_create(from_v: u16, to_v: u16, action: MigrationAction, field: []u8, old_val: []u8, new_val: []u8) MigrationStep {
    return MigrationStep{
        .from_version = from_v,
        .to_version = to_v,
        .action = action,
        .field_name = field,
        .old_value = old_val,
        .new_value = new_val,
        .description = "",
    };
}

/// Create migration step with description
pub fn step_with_description(step: MigrationStep, desc: []u8) MigrationStep {
    return MigrationStep{
        .from_version = step.from_version,
        .to_version = step.to_version,
        .action = step.action,
        .field_name = step.field_name,
        .old_value = step.old_value,
        .new_value = step.new_value,
        .description = desc,
    };
}

/// Create migration result
pub fn result_success(from: u16, to: u16, steps: []MigrationStep) MigrationResult {
    return MigrationResult{
        .result_type = .success,
        .steps = steps,
        .errors = &[_]MigrationError{},
        .from_version = from,
        .to_version = to,
        .backup_path = null,
    };
}

/// Create migration result with errors
pub fn result_failure(from: u16, to: u16, errors: []MigrationError) MigrationResult {
    return MigrationResult{
        .result_type = .failed,
        .steps = &[_]MigrationStep{},
        .errors = errors,
        .from_version = from,
        .to_version = to,
        .backup_path = null,
    };
}

/// Create migration error
pub fn error_create(step_idx: u8, field: []u8, message: []u8, severity: MigrationSeverity) MigrationError {
    return MigrationError{
        .step = step_idx,
        .field = field,
        .message = message,
        .severity = severity,
    };
}

/// Create migration error info
pub fn error_info(message: []u8) MigrationError {
    return error_create(0, "general", message, .error);
}

/// Create migration error warning
pub fn error_warning(message: []u8) MigrationError {
    return error_create(0, "general", message, .warning);
}

/// Run migration plan
pub fn migrate(config_data: *u8, rules: []MigrationRule, context: MigrationContext) MigrationResult {
    const current_version = detect_version(config_data);
    const target_version = MIGRATION_VERSION;

    if (!needs_migration(current_version, target_version)) {
        return MigrationResult{
            .result_type = .skipped,
            .steps = &[_]MigrationStep{},
            .errors = &[_]MigrationError{},
            .from_version = current_version,
            .to_version = target_version,
            .backup_path = null,
        };
    }

    var steps : []MigrationStep = &[_]MigrationStep{};
    var errors : []MigrationError = &[_]MigrationError{};

    for (rules) |rule| {
        const step = apply_rule(rule, config_data);
        steps = append_steps(steps, step);
    }

    return if (errors.len == 0)
        result_success(current_version, target_version, steps)
    else
        result_failure(current_version, target_version, errors);
}

/// Apply single migration rule
pub fn apply_rule(rule: MigrationRule, config_data: *u8) MigrationStep {
    // Check if rule applies and migrate (simplified)
    return step_create(
        MIN_SUPPORTED_VERSION,
        MIGRATION_VERSION,
        .set_default,
        "version",
        "",
        rule.description,
    );
}

/// Create backup path
pub fn backup_path_create(config_path: []u8) []u8 {
    return concat(config_path, BACKUP_SUFFIX);
}

/// Verify backup was created
pub fn backup_verify(backup_path: []u8) bool {
    // Check if backup exists (simplified)
    return false;
}

/// Create default migration context
pub fn context_default() MigrationContext {
    return MigrationContext{
        .dry_run = false,
        .backup_enabled = true,
        .force_migration = false,
        .verbose = false,
    };
}

/// Create migration context for dry run
pub fn context_dry_run() MigrationContext {
    const base = context_default();
    return MigrationContext{
        .dry_run = true,
        .backup_enabled = false,
        .force_migration = false,
        .verbose = false,
    };
}

/// Create migration context with force
pub fn context_force() MigrationContext {
    const base = context_default();
    return MigrationContext{
        .dry_run = false,
        .backup_enabled = true,
        .force_migration = true,
        .verbose = false,
    };
}

/// Create migration context verbose
pub fn context_verbose() MigrationContext {
    const base = context_default();
    return MigrationContext{
        .dry_run = false,
        .backup_enabled = true,
        .force_migration = false,
        .verbose = true,
    };
}

/// Append step to slice
pub fn append_steps(slice: []MigrationStep, item: MigrationStep) []MigrationStep {
    var result : []MigrationStep = slice;
    var new_slice : []MigrationStep = &[_]MigrationStep{item};
    for (result) |_| {
        new_slice = append_steps_slice(new_slice, _);
    }
    return new_slice;
}

/// Append steps slice
pub fn append_steps_slice(slice: []MigrationStep, item: MigrationStep) []MigrationStep {
    var result : []MigrationStep = slice;
    result = concat_steps(result, item);
    return result;
}

/// Concatenate steps
pub fn concat_steps(a: []MigrationStep, b: MigrationStep) []MigrationStep {
    var result : []MigrationStep = a;
    var new_slice : []MigrationStep = &[_]MigrationStep{b};
    for (result) |_| {
        new_slice = append_steps_slice(new_slice, _);
    }
    return new_slice;
}

/// Concatenate steps with string
pub fn concat_steps_string(a: []u8, b: []u8) []u8 {
    var result : []u8 = a;
    for (b) |byte| {
        result = append_byte_steps(result, byte);
    }
    return result;
}

/// Append byte to steps
pub fn append_byte_steps(slice: []MigrationStep, byte: u8) []MigrationStep {
    var result : []MigrationStep = slice;
    result = concat_steps_string(result, &[_]u8{byte});
    return result;
}

/// Append errors to slice
pub fn append_errors(slice: []MigrationError, item: MigrationError) []MigrationError {
    var result : []MigrationError = slice;
    var new_slice : []MigrationError = &[_]MigrationError{item};
    for (result) |_| {
        new_slice = append_errors_slice(new_slice, _);
    }
    return new_slice;
}

/// Append errors slice
pub fn append_errors_slice(slice: []MigrationError, item: MigrationError) []MigrationError {
    var result : []MigrationError = slice;
    result = concat_errors(result, item);
    return result;
}

/// Concatenate errors
pub fn concat_errors(a: []MigrationError, b: MigrationError) []MigrationError {
    var result : []MigrationError = a;
    var new_slice : []MigrationError = &[_]MigrationError{b};
    for (result) |_| {
        new_slice = append_errors_slice(new_slice, _);
    }
    return new_slice;
}

/// Concatenate errors with string
pub fn concat_errors_string(a: []u8, b: []u8) []u8 {
    var result : []u8 = a;
    for (b) |byte| {
        result = append_byte_errors(result, byte);
    }
    return result;
}

/// Append byte to errors
pub fn append_byte_errors(slice: []MigrationError, byte: u8) []MigrationError {
    var result : []MigrationError = slice;
    result = concat_errors_string(result, &[_]u8{byte});
    return result;
}

