test "migrate_detect_version" {
    const version = detect_version(@ptrFrom([]u8{"version":1}));
    try std.testing.expect(version >= MIN_SUPPORTED_VERSION);
}

test "migrate_is_version_supported" {
    try std.testing.expect(is_version_supported(MIN_SUPPORTED_VERSION));
}

test "migrate_needs_migration_true" {
    try std.testing.expect(needs_migration(1, 2));
}

test "migrate_needs_migration_false" {
    try std.testing.expect(!needs_migration(2, 2));
}

test "migrate_step_create" {
    const step = step_create(1, 2, .set_default, "key", "old", "new");
    try std.testing.expect(step.from_version == 1);
}

test "migrate_step_with_description" {
    const base = step_create(1, 2, .set_default, "key", "old", "new");
    const step = step_with_description(base, "Migrate key field");
    try std.testing.expect(step.description.len > 0);
}

test "migrate_result_success" {
    const steps = &[_]MigrationStep{};
    const result = result_success(1, 2, steps);
    try std.testing.expect(result.result_type == .success);
}

test "migrate_result_failure" {
    const errors = &[_]MigrationError{error_info("test error")};
    const result = result_failure(1, 2, errors);
    try std.testing.expect(result.result_type == .failed);
}

test "migrate_error_create" {
    const error = error_create(0, "field", "message", .error);
    try std.testing.expect(error.step == 0);
}

test "migrate_error_info" {
    const error = error_info("test message");
    try std.testing.expect(error.severity == .error);
}

test "migrate_error_warning" {
    const error = error_warning("test warning");
    try std.testing.expect(error.severity == .warning);
}

test "migrate_backup_path_create" {
    const path = backup_path_create("/path/to/config.json");
    try std.testing.expect(std.mem.indexOf(path, BACKUP_SUFFIX) < path.len);
}

test "migrate_context_default" {
    const context = context_default();
    try std.testing.expect(context.backup_enabled);
}

test "migrate_context_dry_run" {
    const context = context_dry_run();
    try std.testing.expect(context.dry_run);
}

test "migrate_context_force" {
    const context = context_force();
    try std.testing.expect(context.force_migration);
}

