pub const HTTP_METHOD_GET : [3]u8 = "GET";

/// HTTP POST method
pub const HTTP_METHOD_POST : [4]u8 = "POST";

/// HTTP PUT method
pub const HTTP_METHOD_PUT : [3]u8 = "PUT";

/// HTTP DELETE method
pub const HTTP_METHOD_DELETE : [6]u8 = "DELETE";

/// Content-Type header for JSON
pub const HEADER_CONTENT_TYPE_JSON : [16]u8 = "Content-Type: application/json";

/// Authorization header
pub const HEADER_AUTHORIZATION : [14]u8 = "Authorization: Bearer ";

/// API version header for Anthropic
pub const HEADER_ANTHROPIC_VERSION : [23]u8 = "anthropic-version: 2023-06-01";

/// HTTP status code OK
pub const STATUS_OK : i32 = 200;

/// HTTP status code Created
pub const STATUS_CREATED : i32 = 201;

/// HTTP status code Unauthorized
pub const STATUS_UNAUTHORIZED : i32 = 401;

/// HTTP status code Forbidden
pub const STATUS_FORBIDDEN : i32 = 403;

/// HTTP status code Not Found
pub const STATUS_NOT_FOUND : i32 = 404;

/// HTTP status code Too Many Requests
pub const STATUS_TOO_MANY_REQUESTS : i32 = 429;

/// HTTP status code Internal Server Error
pub const STATUS_INTERNAL_ERROR : i32 = 500;

/// HTTP status code Service Unavailable
pub const STATUS_SERVICE_UNAVAILABLE : i32 = 503;

/// Anthropic messages endpoint
pub const ENDPOINT_ANTHROPIC_MESSAGES : [27]u8 = "https://api.anthropic.com/v1/messages";

/// OpenAI chat completions endpoint
pub const ENDPOINT_OPENAI_CHAT : [38]u8 = "https://api.openai.com/v1/chat/completions";

// ============================================================================
// Types
// ============================================================================

/// HTTP method
pub const HttpMethod = enum(u8) {
    get = 0,
    post = 1,
    put = 2,
    delete = 3,
};

/// HTTP header
pub const HttpHeader = struct {
    name : []u8,
    value : []u8,
};

/// HTTP request
pub const HttpRequest = struct {
    method : HttpMethod,
    url : []u8,
    headers : []HttpHeader,
    body : []u8,
    timeout_ms : usize,
};

/// HTTP response
pub const HttpResponse = struct {
    status_code : i32,
    headers : []HttpHeader,
    body : []u8,
    success : bool,
};

/// Adapter configuration
pub const AdapterConfig = struct {
    provider_type : ProviderType,
    base_url : []u8,
    api_key : []u8,
    timeout_ms : usize,
    max_retries : usize,
    backoff_ms : usize,
};

/// Retry policy
pub const RetryPolicy = enum(u8) {
    none = 0,
    exponential = 1,
    linear = 2,
    fixed = 3,
};

/// Request adapter result
pub const AdapterResult = struct {
    success : bool,
    response : HttpResponse,
    error : []u8,
};

/// Stream adapter state
pub const StreamAdapterState = enum(u8) {
    idle = 0,
    connecting = 1,
    streaming = 2,
    error = 3,
    closed = 4,
};

/// Stream chunk
pub const StreamChunk = struct {
    data : []u8,
    done : bool,
    error : []u8,
};

/// Rate limit info
pub const RateLimitInfo = struct {
    remaining : usize,
    reset_time : usize,
    limit : usize,
};

/// Authentication info
pub const AuthInfo = struct {
    api_key : []u8,
    auth_type : []u8,
};

// ============================================================================
// Functions
// ============================================================================

/// Create HTTP header
pub fn http_header_create(name: []u8, value: []u8) HttpHeader {
    return HttpHeader{
        .name = name,
        .value = value,
    };
}

/// Create HTTP request
pub fn http_request_create(method: HttpMethod, url: []u8, body: []u8) HttpRequest {
    return HttpRequest{
        .method = method,
        .url = url,
        .headers = &[_]HttpHeader{},
        .body = body,
        .timeout_ms = DEFAULT_TIMEOUT_MS,
    };
}

/// Create HTTP response
pub fn http_response_create(status_code: i32, body: []u8) HttpResponse {
    return HttpResponse{
        .status_code = status_code,
        .headers = &[_]HttpHeader{},
        .body = body,
        .success = status_code >= 200 and status_code < 300,
    };
}

/// Create adapter config
pub fn adapter_config_create(provider_type: ProviderType, api_key: []u8) AdapterConfig {
    const base_url = if (provider_type == .anthropic) {
        ENDPOINT_ANTHROPIC_MESSAGES;
    } else {
        ENDPOINT_OPENAI_CHAT;
    };
    return AdapterConfig{
        .provider_type = provider_type,
        .base_url = base_url,
        .api_key = api_key,
        .timeout_ms = DEFAULT_TIMEOUT_MS,
        .max_retries = DEFAULT_MAX_RETRIES,
        .backoff_ms = DEFAULT_BACKOFF_MS,
    };
}

/// Create stream chunk
pub fn stream_chunk_create(data: []u8, done: bool) StreamChunk {
    return StreamChunk{
        .data = data,
        .done = done,
        .error = "",
    };
}

/// Create stream chunk with error
pub fn stream_chunk_error(error: []u8) StreamChunk {
    return StreamChunk{
        .data = "",
        .done = false,
        .error = error,
    };
}

/// Create rate limit info
pub fn rate_limit_info_create(remaining: usize, reset_time: usize) RateLimitInfo {
    return RateLimitInfo{
        .remaining = remaining,
        .reset_time = reset_time,
        .limit = 0,
    };
}

/// Create authentication info
pub fn auth_info_create(api_key: []u8) AuthInfo {
    return AuthInfo{
        .api_key = api_key,
        .auth_type = "Bearer",
    };
}

/// Create adapter result
pub fn adapter_result_create(response: HttpResponse) AdapterResult {
    return AdapterResult{
        .success = response.success,
        .response = response,
        .error = "",
    };
}

/// Create adapter result with error
pub fn adapter_result_error(error: []u8) AdapterResult {
    return AdapterResult{
        .success = false,
        .response = http_response_create(0, ""),
        .error = error,
    };
}

/// Get method string
pub fn http_method_to_string(method: HttpMethod) []u8 {
    return switch (method) {
        .get => HTTP_METHOD_GET,
        .post => HTTP_METHOD_POST,
        .put => HTTP_METHOD_PUT,
        .delete => HTTP_METHOD_DELETE,
    };
}

/// Get HTTP method from string
pub fn http_method_from_string(s: []u8) HttpMethod {
    if (s == HTTP_METHOD_GET) {
        return .get;
    } else if (s == HTTP_METHOD_POST) {
        return .post;
    } else if (s == HTTP_METHOD_PUT) {
        return .put;
    } else {
        return .delete;
    }
}

/// Check if status code is success
pub fn is_status_success(status_code: i32) bool {
    return status_code >= 200 and status_code < 300;
}

/// Check if status code is client error
pub fn is_status_client_error(status_code: i32) bool {
    return status_code >= 400 and status_code < 500;
}

/// Check if status code is server error
pub fn is_status_server_error(status_code: i32) bool {
    return status_code >= 500 and status_code < 600;
}

/// Check if status code is rate limited
pub fn is_status_rate_limited(status_code: i32) bool {
    return status_code == STATUS_TOO_MANY_REQUESTS;
}

/// Check if status code is unauthorized
pub fn is_status_unauthorized(status_code: i32) bool {
    return status_code == STATUS_UNAUTHORIZED;
}

/// Check if response is successful
pub fn is_response_success(resp: HttpResponse) bool {
    return resp.success;
}

/// Check if adapter result is successful
pub fn is_adapter_success(result: AdapterResult) bool {
    return result.success;
}

/// Build headers for request
pub fn build_headers(api_key: []u8, provider_type: ProviderType) []HttpHeader {
    var headers : []HttpHeader = undefined;
    headers = headers ++ &[_]HttpHeader{
        http_header_create("Authorization", HEADER_AUTHORIZATION ++ api_key),
        http_header_create("Content-Type", "application/json"),
    };
    if (provider_type == .anthropic) {
        headers = headers ++ &[_]HttpHeader{
            http_header_create("anthropic-version", "2023-06-01"),
        };
    }
    return headers;
}

/// Calculate retry delay with backoff
pub fn calculate_retry_delay(attempt: usize, policy: RetryPolicy, base_delay: usize) usize {
    if (policy == .none) {
        return 0;
    } else if (policy == .fixed) {
        return base_delay;
    } else if (policy == .linear) {
        return attempt * base_delay;
    } else {
        const delay = base_delay * @as(usize, 2) ** attempt;
        return if (delay > MAX_BACKOFF_MS) { MAX_BACKOFF_MS } else { delay };
    }
}

/// Get endpoint URL for provider
pub fn get_endpoint(provider_type: ProviderType) []u8 {
    return if (provider_type == .anthropic) {
        ENDPOINT_ANTHROPIC_MESSAGES;
    } else {
        ENDPOINT_OPENAI_CHAT;
    };
}

/// Get endpoint URL for Anthropic messages
pub fn get_endpoint_anthropic() []u8 {
    return ENDPOINT_ANTHROPIC_MESSAGES;
}

/// Get endpoint URL for OpenAI chat
pub fn get_endpoint_openai() []u8 {
    return ENDPOINT_OPENAI_CHAT;
}

