// provider/schema.t27 — Provider Message Types
// AI provider message structures and model types
// φ² + 1/φ² = 3 | TRINITY

module provider-schema;

// ============================================================================
// Imports
// ============================================================================

use tritype-base::usize;

// ============================================================================
// Constants
// ============================================================================

/// Anthropic API provider name
pub const PROVIDER_ANTHROPIC : [9]u8 = "anthropic";

/// OpenAI API provider name
pub const PROVIDER_OPENAI : [6]u8 = "openai";

/// Default provider
pub const PROVIDER_DEFAULT : [9]u8 = PROVIDER_ANTHROPIC;

/// Default model for Anthropic
pub const MODEL_ANTHROPIC_DEFAULT : [18]u8 = "claude-sonnet-4-20250514";

/// Default model for OpenAI
pub const MODEL_OPENAI_DEFAULT : [6]u8 = "gpt-4";

/// Maximum tokens in request
pub const MAX_TOKENS : usize = 128000;

/// Default temperature
pub const DEFAULT_TEMPERATURE : f64 = 0.7;

/// Default max tokens
pub const DEFAULT_MAX_TOKENS : usize = 4096;

/// Default top p value
pub const DEFAULT_TOP_P : f64 = 1.0;

// ============================================================================
// Types
// ============================================================================

/// Provider type
pub const ProviderType = enum(u8) {
    anthropic = 0,
    openai = 1,
};

/// Message role
pub const MessageRole = enum(u8) {
    system = 0,
    user = 1,
    assistant = 2,
    tool = 3,
};

/// Message content type
pub const ContentType = enum(u8) {
    text = 0,
    image = 1,
    tool_use = 2,
    tool_result = 3,
};

/// Message content
pub const MessageContent = struct {
    type : ContentType,
    text : []u8,
    image_url : []u8,
    tool_call_id : []u8,
    tool_result : []u8,
};

/// Message
pub const Message = struct {
    role : MessageRole,
    content : []MessageContent,
};

/// Tool definition
pub const Tool = struct {
    name : []u8,
    description : []u8,
    input_schema : []u8,
};

/// Tool call
pub const ToolCall = struct {
    id : []u8,
    name : []u8,
    arguments : []u8,
};

/// Request parameters
pub const RequestParams = struct {
    model : []u8,
    messages : []Message,
    max_tokens : usize,
    temperature : f64,
    top_p : f64,
    tools : []Tool,
};

/// Streaming chunk type
pub const ChunkType = enum(u8) {
    content = 0,
    tool_call = 1,
    done = 2,
    error = 3,
};

/// Streaming chunk
pub const StreamingChunk = struct {
    chunk_type : ChunkType,
    delta : []u8,
    tool_calls : []ToolCall,
    finish_reason : []u8,
    usage : Usage,
};

/// Token usage
pub const Usage = struct {
    prompt_tokens : usize,
    completion_tokens : usize,
    total_tokens : usize,
};

/// Response
pub const Response = struct {
    id : []u8,
    model : []u8,
    choices : []Choice,
    usage : Usage,
    finish_reason : []u8,
};

/// Choice
pub const Choice = struct {
    message : Message,
    finish_reason : []u8,
};

/// Stream response
pub const StreamResponse = struct {
    id : []u8,
    model : []u8,
    chunks : []StreamingChunk,
};

/// Provider configuration
pub const ProviderConfig = struct {
    provider_type : ProviderType,
    api_key : []u8,
    base_url : []u8,
    model : []u8,
    timeout_ms : usize,
    max_retries : usize,
};

/// Provider capability
pub const ProviderCapability = enum(u8) {
    chat_completion = 0,
    streaming = 1,
    function_calling = 2,
    vision = 3,
};

/// Provider capabilities
pub const ProviderCapabilities = struct {
    chat_completion : bool,
    streaming : bool,
    function_calling : bool,
    vision : bool,
};

/// Error type
pub const ProviderError = struct {
    code : i32,
    message : []u8,
    type : []u8,
};

/// Image content
pub const ImageContent = struct {
    url : []u8,
    detail : []u8,
};

// ============================================================================
// Functions
// ============================================================================

/// Create provider type from string
pub fn provider_type_from_string(s: []u8) ProviderType {
    if (s == PROVIDER_ANTHROPIC) {
        return .anthropic;
    } else if (s == PROVIDER_OPENAI) {
        return .openai;
    } else {
        return .anthropic;
    }
}

/// Get provider type string
pub fn provider_type_to_string(pt: ProviderType) []u8 {
    return switch (pt) {
        .anthropic => PROVIDER_ANTHROPIC,
        .openai => PROVIDER_OPENAI,
    };
}

/// Create message
pub fn message_create(role: MessageRole, text: []u8) Message {
    return Message{
        .role = role,
        .content = &[_]MessageContent{
            MessageContent{
                .type = .text,
                .text = text,
                .image_url = "",
                .tool_call_id = "",
                .tool_result = "",
            },
        },
    };
}

/// Create system message
pub fn system_message_create(text: []u8) Message {
    return message_create(.system, text);
}

/// Create user message
pub fn user_message_create(text: []u8) Message {
    return message_create(.user, text);
}

/// Create tool definition
pub fn tool_create(name: []u8, description: []u8) Tool {
    return Tool{
        .name = name,
        .description = description,
        .input_schema = "",
    };
}

/// Create request params
pub fn request_params_create(model: []u8, messages: []Message) RequestParams {
    return RequestParams{
        .model = model,
        .messages = messages,
        .max_tokens = DEFAULT_MAX_TOKENS,
        .temperature = DEFAULT_TEMPERATURE,
        .top_p = DEFAULT_TOP_P,
        .tools = &[_]Tool{},
    };
}

/// Create provider config
pub fn provider_config_create(provider_type: ProviderType, api_key: []u8) ProviderConfig {
    const base_url = if (provider_type == .anthropic) {
        "https://api.anthropic.com";
    } else {
        "https://api.openai.com";
    };
    return ProviderConfig{
        .provider_type = provider_type,
        .api_key = api_key,
        .base_url = base_url,
        .model = if (provider_type == .anthropic) { MODEL_ANTHROPIC_DEFAULT } else { MODEL_OPENAI_DEFAULT },
        .timeout_ms = 30000,
        .max_retries = 3,
    };
}

/// Create usage
pub fn usage_create(prompt: usize, completion: usize) Usage {
    return Usage{
        .prompt_tokens = prompt,
        .completion_tokens = completion,
        .total_tokens = prompt + completion,
    };
}

/// Create streaming chunk
pub fn streaming_chunk_create(chunk_type: ChunkType, delta: []u8) StreamingChunk {
    return StreamingChunk{
        .chunk_type = chunk_type,
        .delta = delta,
        .tool_calls = &[_]ToolCall{},
        .finish_reason = "",
        .usage = usage_create(0, 0),
    };
}

/// Create response
pub fn response_create(id: []u8, model: []u8, message: Message) Response {
    return Response{
        .id = id,
        .model = model,
        .choices = &[_]Choice{
            Choice{
                .message = message,
                .finish_reason = "stop",
            },
        },
        .usage = usage_create(0, 0),
        .finish_reason = "stop",
    };
}

/// Get role string
pub fn role_to_string(role: MessageRole) []u8 {
    return switch (role) {
        .system => "system",
        .user => "user",
        .assistant => "assistant",
        .tool => "tool",
    };
}

/// Create provider error
pub fn provider_error_create(code: i32, message: []u8) ProviderError {
    return ProviderError{
        .code = code,
        .message = message,
        .type = "ProviderError",
    };
}

/// Check if provider is Anthropic
pub fn is_anthropic_provider(pt: ProviderType) bool {
    return pt == .anthropic;
}

/// Check if provider is OpenAI
pub fn is_openai_provider(pt: ProviderType) bool {
    return pt == .openai;
}

/// Check if response has error
pub fn response_has_error(resp: Response) bool {
    return resp.choices.len == 0;
}

/// Check if chunk is done
pub fn chunk_is_done(chunk: StreamingChunk) bool {
    return chunk.chunk_type == .done;
}

/// Get chunk type string
pub fn chunk_type_to_string(ct: ChunkType) []u8 {
    return switch (ct) {
        .content => "content",
        .tool_call => "tool_call",
        .done => "done",
        .error => "error",
    };
}

