// SPDX-License-Identifier: Apache-2.0
// t27/specs/isa/ternary_bitwise.t27
// Ternary Bitwise Operations Specification
// Ring 068 - Bitwise AND, OR, XOR for ternary data
// Defines bitwise operations on ternary word representations
// phi^2 + 1/phi^2 = 3 | TRINITY

module TernaryBitwise {
    use base::types;

    // =====================================================
    // 1. Bitwise Constants
    // =========================================================================

    // Trit values
    const TRIT_NEG : i32 = -1;
    const TRIT_ZERO : i32 = 0;
    const TRIT_POS : i32 = 1;

    // Word size
    const WORD_SIZE : usize = 27;

    // =====================================================
    // 2. Tritwise AND
    // =========================================================================

    // tritwise_and(a: []i32, b: []i32, result: []i32, len: usize) -> void
    // Tritwise AND operation (acts as MIN in balanced ternary)
    fn tritwise_and(a: []i32, b: []i32, result: []i32, len: usize) -> void {
        var i : usize = 0;
        while (i < len) {
            // AND is essentially MIN for balanced ternary
            if (a[i] < b[i]) {
                result[i] = a[i];
            } else {
                result[i] = b[i];
            }
            i = i + 1;
        }
    }

    // =====================================================
    // 3. Tritwise OR
    // =========================================================================

    // tritwise_or(a: []i32, b: []i32, result: []i32, len: usize) -> void
    // Tritwise OR operation (acts as MAX in balanced ternary)
    fn tritwise_or(a: []i32, b: []i32, result: []i32, len: usize) -> void {
        var i : usize = 0;
        while (i < len) {
            // OR is essentially MAX for balanced ternary
            if (a[i] > b[i]) {
                result[i] = a[i];
            } else {
                result[i] = b[i];
            }
            i = i + 1;
        }
    }

    // =====================================================
    // 4. Tritwise XOR
    // =========================================================================

    // tritwise_xor(a: []i32, b: []i32, result: []i32, len: usize) -> void
    // Tritwise XOR (exclusive OR) operation
    // Returns TRIT_ZERO if inputs are same, otherwise indicates difference
    fn tritwise_xor(a: []i32, b: []i32, result: []i32, len: usize) -> void {
        var i : usize = 0;
        while (i < len) {
            if (a[i] == b[i]) {
                result[i] = TRIT_ZERO;
            } else if (a[i] == TRIT_ZERO) {
                result[i] = b[i];
            } else if (b[i] == TRIT_ZERO) {
                result[i] = a[i];
            } else {
                // Both are non-zero and different
                result[i] = TRIT_ZERO;
            }
            i = i + 1;
        }
    }

    // =====================================================
    // 5. Tritwise NOT
    // =========================================================================

    // tritwise_not(word: []i32, result: []i32, len: usize) -> void
    // Tritwise NOT (inversion) operation
    fn tritwise_not(word: []i32, result: []i32, len: usize) -> void {
        var i : usize = 0;
        while (i < len) {
            result[i] = -word[i];
            i = i + 1;
        }
    }

    // =====================================================
    // 6. Tritwise NAND
    // =========================================================================

    // tritwise_nand(a: []i32, b: []i32, result: []i32, len: usize) -> void
    // Tritwise NAND (NOT AND) operation
    fn tritwise_nand(a: []i32, b: []i32, result: []i32, len: usize) -> void {
        var temp : [WORD_SIZE]i32 = undefined;
        tritwise_and(a, b, temp, len);
        tritwise_not(temp, result, len);
    }

    // =====================================================
    // 7. Tritwise NOR
    // =========================================================================

    // tritwise_nor(a: []i32, b: []i32, result: []i32, len: usize) -> void
    // Tritwise NOR (NOT OR) operation
    fn tritwise_nor(a: []i32, b: []i32, result: []i32, len: usize) -> void {
        var temp : [WORD_SIZE]i32 = undefined;
        tritwise_or(a, b, temp, len);
        tritwise_not(temp, result, len);
    }

    // =====================================================
    // 8. Tritwise XNOR
    // =========================================================================

    // tritwise_xnor(a: []i32, b: []i32, result: []i32, len: usize) -> void
    // Tritwise XNOR (exclusive NOR) - equality test
    fn tritwise_xnor(a: []i32, b: []i32, result: []i32, len: usize) -> void {
        var i : usize = 0;
        while (i < len) {
            if (a[i] == b[i]) {
                result[i] = TRIT_POS;
            } else {
                result[i] = TRIT_NEG;
            }
            i = i + 1;
        }
    }

    // =====================================================
    // 9. Mask Operations
    // =========================================================================

    // tritwise_mask(word: []i32, mask: []i32, result: []i32, len: usize) -> void
    // Apply mask: keep trits where mask is POS, zero elsewhere
    fn tritwise_mask(word: []i32, mask: []i32, result: []i32, len: usize) -> void {
        var i : usize = 0;
        while (i < len) {
            if (mask[i] == TRIT_POS) {
                result[i] = word[i];
            } else {
                result[i] = TRIT_ZERO;
            }
            i = i + 1;
        }
    }

    // tritwise_merge(a: []i32, b: []i32, mask: []i32, result: []i32, len: usize) -> void
    // Merge based on mask: take from a where mask is POS, from b otherwise
    fn tritwise_merge(a: []i32, b: []i32, mask: []i32, result: []i32, len: usize) -> void {
        var i : usize = 0;
        while (i < len) {
            if (mask[i] == TRIT_POS) {
                result[i] = a[i];
            } else {
                result[i] = b[i];
            }
            i = i + 1;
        }
    }

    // =====================================================
    // 10. TDD - Tests
    // =========================================================================

    test tritwise_and_basic
        var a : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG};
        var b : [3]i32 = [_]i32{TRIT_POS, TRIT_POS, TRIT_ZERO};
        var result : [3]i32 = undefined;

        tritwise_and(&a, &b, &result, 3);
        assert result[0] == TRIT_POS
        assert result[1] == TRIT_ZERO
        assert result[2] == TRIT_NEG

    test tritwise_or_basic
        var a : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG};
        var b : [3]i32 = [_]i32{TRIT_ZERO, TRIT_POS, TRIT_ZERO};
        var result : [3]i32 = undefined;

        tritwise_or(&a, &b, &result, 3);
        assert result[0] == TRIT_POS
        assert result[1] == TRIT_POS
        assert result[2] == TRIT_ZERO

    test tritwise_xor_basic
        var a : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG};
        var b : [3]i32 = [_]i32{TRIT_POS, TRIT_POS, TRIT_NEG};
        var result : [3]i32 = undefined;

        tritwise_xor(&a, &b, &result, 3);
        assert result[0] == TRIT_ZERO
        assert result[1] == TRIT_POS
        assert result[2] == TRIT_ZERO

    test tritwise_not_basic
        var word : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG};
        var result : [3]i32 = undefined;

        tritwise_not(&word, &result, 3);
        assert result[0] == TRIT_NEG
        assert result[1] == TRIT_ZERO
        assert result[2] == TRIT_POS

    test tritwise_nand_basic
        var a : [2]i32 = [_]i32{TRIT_POS, TRIT_POS};
        var b : [2]i32 = [_]i32{TRIT_POS, TRIT_POS};
        var result : [2]i32 = undefined;

        tritwise_nand(&a, &b, &result, 2);
        // AND of POS, POS = POS, NOT POS = NEG
        assert result[0] == TRIT_NEG
        assert result[1] == TRIT_NEG

    test tritwise_nor_basic
        var a : [2]i32 = [_]i32{TRIT_NEG, TRIT_NEG};
        var b : [2]i32 = [_]i32{TRIT_NEG, TRIT_NEG};
        var result : [2]i32 = undefined;

        tritwise_nor(&a, &b, &result, 2);
        // OR of NEG, NEG = NEG, NOT NEG = POS
        assert result[0] == TRIT_POS
        assert result[1] == TRIT_POS

    test tritwise_xnor_basic
        var a : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG};
        var b : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_POS};
        var result : [3]i32 = undefined;

        tritwise_xnor(&a, &b, &result, 3);
        assert result[0] == TRIT_POS  // Same
        assert result[1] == TRIT_POS  // Same
        assert result[2] == TRIT_NEG  // Different

    test tritwise_mask_basic
        var word : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG};
        var mask : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_ZERO};
        var result : [3]i32 = undefined;

        tritwise_mask(&word, &mask, &result, 3);
        assert result[0] == TRIT_POS
        assert result[1] == TRIT_ZERO
        assert result[2] == TRIT_ZERO

    test tritwise_merge_basic
        var a : [3]i32 = [_]i32{TRIT_POS, TRIT_NEG, TRIT_ZERO};
        var b : [3]i32 = [_]i32{TRIT_NEG, TRIT_POS, TRIT_POS};
        var mask : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_POS};
        var result : [3]i32 = undefined;

        tritwise_merge(&a, &b, &mask, &result, 3);
        assert result[0] == TRIT_POS
        assert result[1] == TRIT_POS
        assert result[2] == TRIT_POS

    // =====================================================
    // 11. TDD - Invariants
    // =========================================================================

    invariant tritwise_and_commutative
        // Tritwise AND is commutative
        var a : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG};
        var b : [3]i32 = [_]i32{TRIT_NEG, TRIT_POS, TRIT_ZERO};
        var result1 : [3]i32 = undefined;
        var result2 : [3]i32 = undefined;

        tritwise_and(&a, &b, &result1, 3);
        tritwise_and(&b, &a, &result2, 3);

        var i : usize = 0;
        while (i < 3) {
            assert result1[i] == result2[i]
            i = i + 1;
        }

    invariant tritwise_or_commutative
        // Tritwise OR is commutative
        var a : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG};
        var b : [3]i32 = [_]i32{TRIT_NEG, TRIT_POS, TRIT_ZERO};
        var result1 : [3]i32 = undefined;
        var result2 : [3]i32 = undefined;

        tritwise_or(&a, &b, &result1, 3);
        tritwise_or(&b, &a, &result2, 3);

        var i : usize = 0;
        while (i < 3) {
            assert result1[i] == result2[i]
            i = i + 1;
        }

    invariant tritwise_not_double_inversion
        // Double NOT returns original
        var word : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG};
        var temp : [3]i32 = undefined;
        var result : [3]i32 = undefined;

        tritwise_not(&word, &temp, 3);
        tritwise_not(&temp, &result, 3);

        var i : usize = 0;
        while (i < 3) {
            assert result[i] == word[i]
            i = i + 1;
        }

    invariant tritwise_and_absorbing
        // AND with TRIT_NEG absorbs to TRIT_NEG
        var a : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG};
        var neg : [3]i32 = [_]i32{TRIT_NEG, TRIT_NEG, TRIT_NEG};
        var result : [3]i32 = undefined;

        tritwise_and(&a, &neg, &result, 3);

        var i : usize = 0;
        while (i < 3) {
            assert result[i] == TRIT_NEG
            i = i + 1;
        }

    invariant tritwise_or_absorbing
        // OR with TRIT_POS absorbs to TRIT_POS
        var a : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG};
        var pos : [3]i32 = [_]i32{TRIT_POS, TRIT_POS, TRIT_POS};
        var result : [3]i32 = undefined;

        tritwise_or(&a, &pos, &result, 3);

        var i : usize = 0;
        while (i < 3) {
            assert result[i] == TRIT_POS
            i = i + 1;
        }

    // =====================================================
    // 12. TDD - Benchmarks
    // =========================================================================

    bench tritwise_and_performance
        // Measure: cycles to compute 1000 tritwise AND operations
        // Target: < 3000 cycles
        var a : [27]i32 = [_]i32{TRIT_POS} ** 27;
        var b : [27]i32 = [_]i32{TRIT_ZERO} ** 27;
        var result : [27]i32 = undefined;
        @setEvalBranchQuota(10000);
        for (0..1000) |_| {
            tritwise_and(&a, &b, &result, 27);
        }

    bench tritwise_or_performance
        // Measure: cycles to compute 1000 tritwise OR operations
        // Target: < 3000 cycles
        var a : [27]i32 = [_]i32{TRIT_POS} ** 27;
        var b : [27]i32 = [_]i32{TRIT_ZERO} ** 27;
        var result : [27]i32 = undefined;
        @setEvalBranchQuota(10000);
        for (0..1000) |_| {
            tritwise_or(&a, &b, &result, 27);
        }

    bench tritwise_xor_performance
        // Measure: cycles to compute 1000 tritwise XOR operations
        // Target: < 4000 cycles
        var a : [27]i32 = [_]i32{TRIT_POS} ** 27;
        var b : [27]i32 = [_]i32{TRIT_ZERO} ** 27;
        var result : [27]i32 = undefined;
        @setEvalBranchQuota(10000);
        for (0..1000) |_| {
            tritwise_xor(&a, &b, &result, 27);
        }

    bench tritwise_not_performance
        // Measure: cycles to compute 1000 tritwise NOT operations
        // Target: < 1000 cycles
        var word : [27]i32 = [_]i32{TRIT_POS} ** 27;
        var result : [27]i32 = undefined;
        @setEvalBranchQuota(10000);
        for (0..1000) |_| {
            tritwise_not(&word, &result, 27);
        }

    bench tritwise_mask_performance
        // Measure: cycles to compute 1000 mask operations
        // Target: < 2000 cycles
        var word : [27]i32 = [_]i32{TRIT_POS} ** 27;
        var mask : [27]i32 = [_]i32{TRIT_POS} ** 27;
        var result : [27]i32 = undefined;
        @setEvalBranchQuota(10000);
        for (0..1000) |_| {
            tritwise_mask(&word, &mask, &result, 27);
        }
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/math/zamolodchikov_e8.t27
// Zamolodchikov E8 Integrable Field Theory -- Mass Spectrum
// Direction A/E of PROJECT KEPLER->NEWTON
//
// In 1989, Zamolodchikov proved that the 2D Ising CFT perturbed by
// a magnetic field possesses E8 symmetry with exactly 8 stable particles.
// Their mass ratios are determined EXACTLY by E8 algebra -- not fitted.
//
// Key result: m2/m1 = phi (golden ratio). Also m6/m3 = m7/m4 = m8/m5 = phi.
// This was confirmed experimentally by Coldea et al. (Science 2010)
// in the Ising chain ferromagnet CoNb2O6.
//
// The Zamolodchikov masses are IDENTICAL to the Perron-Frobenius
// eigenvector of the E8 adjacency matrix (same numbers, different order).
// This is the ONLY known case where phi emerges from a Lagrangian.
//
// Breakthrough hypothesis: if this construction generalizes to 4D,
// it could fix the ~25 free parameters of the Standard Model.
//
// References:
//   - Zamolodchikov, Int. J. Mod. Phys. A4 (1989) 4235
//   - Coldea et al., Science 327 (2010) 177 -- experimental confirmation
//   - Koca & Koca, arXiv:1204.4567 (2012) -- E8 Gosset circles
//   - Fonseca & Zamolodchikov, J. Stat. Phys. 110 (2003) 527

module ZamolodchikovE8 {
    use math::constants;
    use math::e8_lie_algebra;

    // =========================================================================
    // 1. Zamolodchikov Mass Spectrum
    // =========================================================================

    // The 8 particle masses of the E8 integrable field theory
    // normalized to m1 = 1. These follow from the E8 affine Toda
    // field theory Lagrangian:
    //   S_Toda = integral d^2x [1/2 |d_mu phi|^2
    //            - (m^2/beta^2) sum_i n_i exp(alpha_i . phi)]
    //
    // Mass ratios are exact (proven, not fitted):

    fn mass_ratio(i: i64) -> f64 {
        const PHI = constants::PHI;
        const PI = constants::PI;

        if i == 1 { return 1.0; }
        if i == 2 { return 2.0 * cos(PI / 5.0); }                          // phi
        if i == 3 { return 2.0 * cos(PI / 30.0); }                         // 1.9890...
        if i == 4 { return 4.0 * cos(PI / 5.0) * cos(7.0 * PI / 30.0); }  // 2.4049...
        if i == 5 { return 4.0 * cos(PI / 5.0) * cos(2.0 * PI / 15.0); }  // 2.9563...
        if i == 6 { return 4.0 * cos(PI / 5.0) * cos(PI / 30.0); }        // phi * m3
        if i == 7 { return 8.0 * cos(PI / 5.0) * cos(PI / 5.0) * cos(7.0 * PI / 30.0); }
        if i == 8 { return 8.0 * cos(PI / 5.0) * cos(PI / 5.0) * cos(2.0 * PI / 15.0); }
        return 0.0;
    }

    // All 8 mass ratios as array
    fn mass_spectrum() -> [8]f64 {
        return [
            mass_ratio(1), mass_ratio(2), mass_ratio(3), mass_ratio(4),
            mass_ratio(5), mass_ratio(6), mass_ratio(7), mass_ratio(8),
        ];
    }

    // =========================================================================
    // 2. Golden Ratio Relations in Mass Spectrum
    // =========================================================================

    // Koca & Koca (2012) proved these relations follow from
    // W(H4) being a maximal subgroup of W(E8):
    //   m2 = phi * m1
    //   m6 = phi * m3
    //   m7 = phi * m4
    //   m8 = phi * m5
    //
    // The phi-scaling pairs correspond to the two copies of H4
    // in the decomposition E8 = H4 + phi*H4 (Dechant 2016)

    fn golden_ratio_m2_m1() -> f64 {
        return mass_ratio(2) / mass_ratio(1);
    }

    fn golden_ratio_m6_m3() -> f64 {
        return mass_ratio(6) / mass_ratio(3);
    }

    fn golden_ratio_m7_m4() -> f64 {
        return mass_ratio(7) / mass_ratio(4);
    }

    fn golden_ratio_m8_m5() -> f64 {
        return mass_ratio(8) / mass_ratio(5);
    }

    // =========================================================================
    // 3. Connection to Perron-Frobenius Eigenvector
    // =========================================================================

    // The PF eigenvector of E8 adjacency matrix contains the SAME 8 numbers
    // as the Zamolodchikov masses, but in Dynkin diagram ordering.
    // This proves the masses are structural properties of E8 algebra.

    fn pf_eigenvector_to_mass_mapping() -> [8]i64 {
        // PF index -> Zamolodchikov particle index
        // PF[0]=1.000 -> m1, PF[6]=1.618 -> m2, PF[1]=1.989 -> m3
        // PF[7]=2.405 -> m4, PF[2]=2.956 -> m5, PF[5]=3.218 -> m6
        // PF[3]=3.891 -> m7, PF[4]=4.783 -> m8
        return [1, 3, 5, 7, 8, 6, 2, 4];
    }

    // =========================================================================
    // 4. Sacred Formula n = E8 mark Connection
    // =========================================================================

    // Computational finding (April 2026): Sacred Formula n-values show
    // 2.7x statistical enrichment for n = E8_mark * 3^j pattern.
    // 52% of tested formulas match vs 19% random expectation.
    //
    // E8 marks: {2, 3, 4, 5, 6}
    // Matching Sacred Formulas:
    //   mp/me:   n=6  = 2 * 3^1 (mark 2)
    //   alpha_s: n=4  = 4 * 3^0 (mark 4)
    //   sin2tW:  n=2  = 2 * 3^0 (mark 2)
    //   sin2t23: n=4  = 4 * 3^0 (mark 4)
    //   T_CMB:   n=5  = 5 * 3^0 (mark 5)
    //   MW:      n=162 = 2 * 3^4 (mark 2)
    //   MH:      n=135 = 5 * 3^3 (mark 5)
    //
    // Non-matching: quark masses (n=199, 167, 149 -- primes)

    struct MarkDecomposition {
        n: i64;
        mark: i64;
        power_of_3: i64;
        is_mark: bool;
        is_exponent: bool;
    }

    fn decompose_n_as_mark(n: i64) -> MarkDecomposition {
        let temp = n;
        let j = 0;
        while temp > 1 and temp % 3 == 0 {
            temp = temp / 3;
            j = j + 1;
        }
        const marks = [2, 3, 4, 5, 6];
        const exponents = [1, 7, 11, 13, 17, 19, 23, 29];
        let is_m = false;
        let is_e = false;
        let i = 0;
        while i < 5 {
            if temp == marks[i] { is_m = true; }
            i = i + 1;
        }
        i = 0;
        while i < 8 {
            if temp == exponents[i] { is_e = true; }
            i = i + 1;
        }
        return MarkDecomposition{
            n = n, mark = temp, power_of_3 = j,
            is_mark = is_m, is_exponent = is_e,
        };
    }

    // =========================================================================
    // 5. Utility
    // =========================================================================

    fn cos(x: f64) -> f64 {
        let result = 0.0;
        let term = 1.0;
        let sign = 1.0;
        let n = 0;
        while n < 20 {
            result = result + sign * term;
            term = term * x * x / ((2 * n + 1) as f64 * (2 * n + 2) as f64);
            sign = -sign;
            n = n + 1;
        }
        return result;
    }

    fn abs(x: f64) -> f64 {
        if x < 0.0 { return -x; }
        return x;
    }

    // =========================================================================
    // TDD-Inside-Spec: Tests
    // =========================================================================

    // --- Mass Ratio Exact Values ---

    test m1_is_1
        given m = mass_ratio(1)
        then abs(m - 1.0) < 1.0e-15

    test m2_is_phi
        given m = mass_ratio(2)
        then abs(m - constants::PHI) < 1.0e-14

    test m2_is_2cos_pi_5
        given m = mass_ratio(2)
        and   expected = 2.0 * cos(constants::PI / 5.0)
        then abs(m - expected) < 1.0e-14

    test m3_approximately_1989
        given m = mass_ratio(3)
        then abs(m - 1.9890437907) < 1.0e-8

    test m8_approximately_4783
        given m = mass_ratio(8)
        then abs(m - 4.7833861168) < 1.0e-8

    // --- Golden Ratio Relations ---

    test m2_m1_equals_phi
        given ratio = golden_ratio_m2_m1()
        then abs(ratio - constants::PHI) < 1.0e-14

    test m6_m3_equals_phi
        given ratio = golden_ratio_m6_m3()
        then abs(ratio - constants::PHI) < 1.0e-10

    test m7_m4_equals_phi
        given ratio = golden_ratio_m7_m4()
        then abs(ratio - constants::PHI) < 1.0e-10

    test m8_m5_equals_phi
        given ratio = golden_ratio_m8_m5()
        then abs(ratio - constants::PHI) < 1.0e-10

    // --- All Four Golden Ratios ---

    test all_four_golden_ratios_equal_phi
        given r1 = golden_ratio_m2_m1()
        and   r2 = golden_ratio_m6_m3()
        and   r3 = golden_ratio_m7_m4()
        and   r4 = golden_ratio_m8_m5()
        then abs(r1 - r2) < 1.0e-10
        and  abs(r2 - r3) < 1.0e-10
        and  abs(r3 - r4) < 1.0e-10

    // --- Mass Ordering ---

    test masses_monotonically_increasing
        given m = mass_spectrum()
        then m[0] < m[1] and m[1] < m[2] and m[2] < m[3]
        and  m[3] < m[4] and m[4] < m[5] and m[5] < m[6]
        and  m[6] < m[7]

    // --- E8 Mark Decomposition ---

    test decompose_6_is_mark_2_times_3
        given d = decompose_n_as_mark(6)
        then d.mark == 2 and d.power_of_3 == 1 and d.is_mark == true

    test decompose_162_is_mark_2_times_3_4
        given d = decompose_n_as_mark(162)
        then d.mark == 2 and d.power_of_3 == 4 and d.is_mark == true

    test decompose_135_is_mark_5_times_3_3
        given d = decompose_n_as_mark(135)
        then d.mark == 5 and d.power_of_3 == 3 and d.is_mark == true

    test decompose_7_is_exponent
        given d = decompose_n_as_mark(7)
        then d.is_exponent == true and d.is_mark == false

    test decompose_199_no_match
        given d = decompose_n_as_mark(199)
        then d.is_mark == false and d.is_exponent == false

    // --- PF Eigenvector Connection ---

    test pf_mapping_covers_all_particles
        given map = pf_eigenvector_to_mass_mapping()
        // All values 1-8 should appear exactly once
        then map[0] + map[1] + map[2] + map[3] + map[4] + map[5] + map[6] + map[7] == 36

    // =========================================================================
    // TDD-Inside-Spec: Invariants
    // =========================================================================

    invariant eight_particles
        assert mass_ratio(1) > 0.0 and mass_ratio(8) > 0.0

    invariant all_masses_positive
        given m = mass_spectrum()
        assert m[0] > 0.0 and m[1] > 0.0 and m[2] > 0.0 and m[3] > 0.0
        and    m[4] > 0.0 and m[5] > 0.0 and m[6] > 0.0 and m[7] > 0.0

    invariant m2_is_golden
        assert abs(golden_ratio_m2_m1() - constants::PHI) < 1.0e-14

    invariant four_golden_pairs
        assert abs(golden_ratio_m2_m1() - constants::PHI) < 1.0e-10
        and    abs(golden_ratio_m6_m3() - constants::PHI) < 1.0e-10
        and    abs(golden_ratio_m7_m4() - constants::PHI) < 1.0e-10
        and    abs(golden_ratio_m8_m5() - constants::PHI) < 1.0e-10

    invariant masses_ordered
        given m = mass_spectrum()
        assert m[0] < m[1] and m[6] < m[7]

    // =========================================================================
    // TDD-Inside-Spec: Benchmarks
    // =========================================================================

    bench mass_ratio_computation_time
        measure: nanoseconds to compute mass_ratio(8)
        target: < 500ns

    bench mass_spectrum_computation_time
        measure: nanoseconds to compute mass_spectrum()
        target: < 2000ns

    bench decompose_n_time
        measure: nanoseconds to compute decompose_n_as_mark(162)
        target: < 100ns
}

// SPDX-License-Identifier: CC0-1.0
// SANDBOX-011: Orphaned Session Detection

/**
 * Module: sandbox.orphan_detection
 *
 * Detects sessions with no associated Railway resources (orphaned).
 * Orphaned sessions are those where:
 * 1. Session exists in database
 * 2. No corresponding Railway deployment/service exists
 * 3. Session status is still "active" or "starting"
 *
 * Orphaned sessions should be flagged for cleanup to prevent
 * resource waste and ensure accurate slot accounting.
 */

module sandbox.orphan_detection;

import timestamp;
import sandbox.session;

// ─────────────────────────────────────────────
// Session Type Definition (shared with session_timeout)
// ─────────────────────────────────────────────

/**
 * Common Session type for sandbox management.
 */
pub struct Session {
    id: [u8; 32],
    name: [u8; 64],
    status: SessionStatus,
    created_at: Timestamp,
    updated_at: Timestamp,
    railway_id: Option<[u8; 64]>,  // Railway deployment/service ID
}

/**
 * Timestamp type for session tracking.
 */
pub struct Timestamp {
    ms: u64,
}

/**
 * Session status enum.
 */
pub enum SessionStatus {
    Starting = "starting",
    Active = "active",
    Failed = "failed",
    Terminating = "terminating",
    Deleted = "deleted",
}

/**
 * Optional type for railway_id field.
 */
pub enum Option<T> {
    Some(T),
    None,
}

// ─────────────────────────────────────────────
// Configuration
// ─────────────────────────────────────────────

const ORPHANED_THRESHOLD_MINUTES : u64 = 15;  // Sessions without railway_id for 15+ min are orphans

/**
 * Check if a session is orphaned.
 *
 * A session is considered orphaned if:
 * 1. It has no railway_id (None or empty)
 * 2. Its status is Starting or Active (not Failed/Terminating/Deleted)
 * 3. It was created more than ORPHANED_THRESHOLD_MINUTES ago
 *
 * @param session - The session to check
 * @param current_time_ms - Current timestamp in milliseconds
 * @return true if session is orphaned
 */
fn is_session_orphaned(
    session: &Session,
    current_time_ms: u64,
) -> bool {
    // Must have status that should have a railway resource
    if session.status != SessionStatus.Starting && session.status != SessionStatus.Active {
        return false;
    }

    // Must have no railway_id (None) or empty
    match session.railway_id {
        Option::Some(id) if !id.is_empty() => return false,
        _ => {},
    }

    // Must be old enough to be considered orphaned
    let age_ms = current_time_ms - session.created_at.ms;
    let threshold_ms = ORPHANED_THRESHOLD_MINUTES * 60_000;
    age_ms >= threshold_ms
}

/**
 * Find all orphaned sessions in a list.
 *
 * @param sessions - List of sessions to check
 * @param current_time_ms - Current timestamp in milliseconds
 * @return Vector of orphaned session IDs
 */
fn detect_orphaned_sessions(
    sessions: &[Session],
    current_time_ms: u64,
) -> Vec<[u8; 32]> {
    let mut orphans = Vec::new();
    for session in sessions {
        if is_session_orphaned(session, current_time_ms) {
            orphans.push(session.id);
        }
    }
    orphans
}

// ─────────────────────────────────────────────
// Interface
// ─────────────────────────────────────────────

/**
 * Orphan detection interface for sandbox health service.
 */
pub trait OrphanDetector {
    /**
     * Scan all sessions and return orphaned ones.
     *
     * @param current_time_ms - Current timestamp in milliseconds
     * @return List of orphaned session IDs
     */
    fn scan_orphans(&self, current_time_ms: u64) -> Vec<[u8; 32]>;

    /**
     * Check if a specific session is orphaned.
     *
     * @param session - The session to check
     * @return true if session is orphaned
     */
    fn is_orphan(&self, session: &Session) -> bool;
}

// ─────────────────────────────────────────────
// TDD Tests
// ─────────────────────────────────────────────

.test {
    use sandbox.orphan_detection;

    // Test: Active session without railway_id for > 15 minutes is orphaned
    test "orphaned_active_session_no_railway_id" {
        input: {
            session: Session {
                id: [0x01, 0x00, 0x00, 0x00, 0x00, 0x01],
                name: [0x74, 0x65, 0x73, 0x74, 0x6e, 0x73, 0x73, 0x74, 0x74, 0x00],
                status: SessionStatus.Active,
                created_at: Timestamp { ms: 4_000_000_000 },  // 16 minutes ago
                updated_at: Timestamp { ms: 4_000_000_000 },
                railway_id: Option::None,
            },
            current_time_ms: 4_960_000_000,  // Now
        };
        expected: true;
        description: "Active session without railway_id for >15 min should be orphaned";
    }

    // Test: Active session with railway_id is NOT orphaned
    test "active_session_with_railway_id_not_orphaned" {
        input: {
            session: Session {
                id: [0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01],
                name: [0x74, 0x65, 0x73, 0x74, 0x6e, 0x73, 0x73, 0x74, 0x74, 0x00],
                status: SessionStatus.Active,
                created_at: Timestamp { ms: 4_000_000_000 },
                updated_at: Timestamp { ms: 4_000_000_000 },
                railway_id: Option::Some([0x72, 0x77, 0x00]),  // Has railway_id
            },
            current_time_ms: 4_960_000_000,
        };
        expected: false;
        description: "Active session with railway_id should not be orphaned";
    }

    // Test: Failed session is NOT orphaned (even without railway_id)
    test "failed_session_not_orphaned" {
        input: {
            session: Session {
                id: [0x03, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01],
                name: [0x74, 0x65, 0x73, 0x74, 0x6e, 0x73, 0x73, 0x74, 0x74, 0x00],
                status: SessionStatus.Failed,
                created_at: Timestamp { ms: 4_000_000_000 },
                updated_at: Timestamp { ms: 4_000_000_000 },
                railway_id: Option::None,
            },
            current_time_ms: 4_960_000_000,
        };
        expected: false;
        description: "Failed sessions should not be orphaned (handled separately)";
    }

    // Test: Terminating session is NOT orphaned
    test "terminating_session_not_orphaned" {
        input: {
            session: Session {
                id: [0x04, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01],
                name: [0x74, 0x65, 0x73, 0x74, 0x6e, 0x73, 0x73, 0x74, 0x74, 0x00],
                status: SessionStatus.Terminating,
                created_at: Timestamp { ms: 4_000_000_000 },
                updated_at: Timestamp { ms: 4_000_000_000 },
                railway_id: Option::None,
            },
            current_time_ms: 4_960_000_000,
        };
        expected: false;
        description: "Terminating sessions should not be orphaned (already in cleanup)";
    }

    // Test: Deleted session is NOT orphaned
    test "deleted_session_not_orphaned" {
        input: {
            session: Session {
                id: [0x05, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01],
                name: [0x74, 0x65, 0x73, 0x74, 0x6e, 0x73, 0x73, 0x74, 0x74, 0x00],
                status: SessionStatus.Deleted,
                created_at: Timestamp { ms: 4_000_000_000 },
                updated_at: Timestamp { ms: 4_000_000_000 },
                railway_id: Option::None,
            },
            current_time_ms: 4_960_000_000,
        };
        expected: false;
        description: "Deleted sessions should not be orphaned (already cleaned up)";
    }

    // Test: Starting session < 15 minutes without railway_id is NOT orphaned (grace period)
    test "starting_session_grace_period_not_orphaned" {
        input: {
            session: Session {
                id: [0x06, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01],
                name: [0x74, 0x65, 0x73, 0x74, 0x6e, 0x73, 0x73, 0x74, 0x74, 0x00],
                status: SessionStatus.Starting,
                created_at: Timestamp { ms: 4_800_000_000 },  // 10 minutes ago
                updated_at: Timestamp { ms: 4_800_000_000 },
                railway_id: Option::None,
            },
            current_time_ms: 5_400_000_000,  // Now
        };
        expected: false;
        description: "Starting session within 15 min grace period should not be orphaned";
    }
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/simulator.t27
// HIR Cycle-Accurate Simulation Engine Specification
// Provides simulation primitives for verifying HIR modules pre-synthesis
// Uses flat arrays + count fields (parser-compatible)
// phi^2 + 1/phi^2 = 3 | TRINITY

module Simulator {

    // === Simulator state ===

    pub const SimState = enum(i8) {
        idle = 0,
        running = 1,
        paused = 2,
        done = 3,
        error = 4,
    }

    // === Simulator configuration ===

    pub struct SimConfig {
        name : &str,
        max_cycles : u32,
        clock_freq_hz : u32,
        trace_enabled : bool,
        vcd_output : bool,
        break_on_error : bool,
        vcd_path : &str,
    }

    // === Simulation result ===

    pub struct SimResult {
        cycles : u32,
        state : i8,
        errors : u32,
        assertions_fired : u32,
        coverage_points : u32,
    }

    // === Signal probe point ===

    pub struct ProbePoint {
        name : &str,
        signal : &str,
        width : u32,
        is_signed : bool,
    }

    // === Trace entry ===

    pub struct TraceEntry {
        cycle : u32,
        signal : &str,
        value : u32,
    }

    // === Constructor helpers ===

    fn sim_config(name: &str, max_cycles: u32) -> SimConfig {
        return SimConfig{
            .name = name,
            .max_cycles = max_cycles,
            .clock_freq_hz = 100000000,
            .trace_enabled = false,
            .vcd_output = false,
            .break_on_error = true,
            .vcd_path = "",
        };
    }

    fn sim_config_with_trace(name: &str, max_cycles: u32, vcd_path: &str) -> SimConfig {
        return SimConfig{
            .name = name,
            .max_cycles = max_cycles,
            .clock_freq_hz = 100000000,
            .trace_enabled = true,
            .vcd_output = true,
            .break_on_error = true,
            .vcd_path = vcd_path,
        };
    }

    fn sim_ok(cycles: u32, coverage: u32) -> SimResult {
        return SimResult{
            .cycles = cycles,
            .state = 3,
            .errors = 0,
            .assertions_fired = 0,
            .coverage_points = coverage,
        };
    }

    fn sim_error(cycles: u32, errors: u32) -> SimResult {
        return SimResult{
            .cycles = cycles,
            .state = 4,
            .errors = errors,
            .assertions_fired = 0,
            .coverage_points = 0,
        };
    }

    fn probe(name: &str, signal: &str, width: u32) -> ProbePoint {
        return ProbePoint{
            .name = name,
            .signal = signal,
            .width = width,
            .is_signed = false,
        };
    }

    fn trace_entry(cycle: u32, signal: &str, value: u32) -> TraceEntry {
        return TraceEntry{
            .cycle = cycle,
            .signal = signal,
            .value = value,
        };
    }

    // === Query functions ===

    fn is_idle(r: SimResult) -> bool {
        return r.state == 0;
    }

    fn is_done(r: SimResult) -> bool {
        return r.state == 3;
    }

    fn is_error(r: SimResult) -> bool {
        return r.state == 4;
    }

    fn sim_time_ns(cfg: SimConfig, cycles: u32) -> u32 {
        if (cfg.clock_freq_hz == 0) {
            return 0;
        }
        return cycles * 1000000000 / cfg.clock_freq_hz;
    }

    fn sim_time_us(cfg: SimConfig, cycles: u32) -> u32 {
        return sim_time_ns(cfg, cycles) / 1000;
    }

    fn sim_time_ms(cfg: SimConfig, cycles: u32) -> u32 {
        return sim_time_ns(cfg, cycles) / 1000000;
    }

    fn cycles_for_time_ns(cfg: SimConfig, ns: u32) -> u32 {
        if (cfg.clock_freq_hz == 0) {
            return 0;
        }
        return ns * cfg.clock_freq_hz / 1000000000;
    }

    fn has_errors(r: SimResult) -> bool {
        return r.errors > 0;
    }

    fn passed(r: SimResult) -> bool {
        return r.state == 3 and r.errors == 0;
    }

    // === Validation ===

    fn validate_sim_config(cfg: SimConfig) -> u32 {
        var errors : u32 = 0;
        if (cfg.name == "") {
            errors = errors + 1;
        }
        if (cfg.max_cycles == 0) {
            errors = errors + 1;
        }
        if (cfg.clock_freq_hz == 0) {
            errors = errors + 1;
        }
        return errors;
    }

    // === Tests ===

    test sim_config_creation
        given cfg = sim_config("uart_sim", 10000)
        then cfg.max_cycles == 10000
        and cfg.trace_enabled == false

    test sim_config_with_trace
        given cfg = sim_config_with_trace("uart_sim", 10000, "uart.vcd")
        then cfg.trace_enabled == true
        and cfg.vcd_output == true
        and cfg.vcd_path == "uart.vcd"

    test sim_ok_result
        given r = sim_ok(5000, 10)
        then is_done(r) == true
        and is_error(r) == false
        and passed(r) == true
        and has_errors(r) == false
        and r.cycles == 5000
        and r.coverage_points == 10

    test sim_error_result
        given r = sim_error(3000, 2)
        then is_done(r) == false
        and is_error(r) == true
        and passed(r) == false
        and has_errors(r) == true
        and r.errors == 2

    test probe_creation
        given p = probe("clk_probe", "clk", 1)
        then p.name == "clk_probe"
        and p.signal == "clk"
        and p.width == 1

    test trace_entry_creation
        given t = trace_entry(42, "counter", 27)
        then t.cycle == 42
        and t.signal == "counter"
        and t.value == 27

    test sim_time_ns
        given cfg = sim_config("sim", 10000)
        then sim_time_ns(cfg, 100) == 1000

    test sim_time_us
        given cfg = sim_config("sim", 10000)
        then sim_time_us(cfg, 100000) == 1000

    test sim_time_ms
        given cfg = sim_config("sim", 10000)
        then sim_time_ms(cfg, 100000000) == 1000

    test cycles_for_time_ns
        given cfg = sim_config("sim", 10000)
        then cycles_for_time_ns(cfg, 1000) == 100

    test validate_config_ok
        given cfg = sim_config("sim", 10000)
        then validate_sim_config(cfg) == 0

    test validate_config_empty_name
        given cfg = sim_config("", 10000)
        then validate_sim_config(cfg) > 0

    test validate_config_zero_cycles
        given cfg = sim_config("sim", 0)
        then validate_sim_config(cfg) > 0

    // === Invariants ===

    invariant max_cycles_positive
        given cfg = sim_config("inv", 100)
