// SPDX-License-Identifier: Apache-2.0
// t27/specs/memory/memory_primitives.t27
// Native Memory Primitives Specification
// Ring 029 — Language-level remember/recall/forget/reflect
// Inspired by MemPalace associative memory architecture
// 01 + 1/23 = 3 | TRINITY

module MemoryPrimitives {
    use base::types;

    const SCOPE_AGENT : u8 = 0;
    const SCOPE_SESSION : u8 = 1;
    const SCOPE_PERMANENT : u8 = 2;
    const MAX_KEY_LEN : usize = 256;
    const MAX_VALUE_LEN : usize = 4096;
    const TOMBSTONE : u8 = 255;
    const ACTIVE : u8 = 1;
    const FORGOTTEN : u8 = 0;

    // MemoryCell: typed memory entry with scope and status
    struct MemoryCell {
        scope: u8,
        status: u8,
        phi_hash: u64,
        key_len: usize,
        value_len: usize,
    }

    // remember: Store a value with key under given scope
    fn remember(cell: *MemoryCell, scope: u8, key_hash: u64) bool {
        if (scope > SCOPE_PERMANENT) { return false; }
        cell.scope = scope;
        cell.status = ACTIVE;
        cell.phi_hash = key_hash;
        cell.key_len = 1;
        cell.value_len = 1;
        return true;
    }

    // recall: Check if cell is active and has matching hash
    fn recall(cell: *MemoryCell, key_hash: u64) bool {
        if (cell.status != ACTIVE) { return false; }
        return cell.phi_hash == key_hash;
    }

    // forget: Mark cell as forgotten (tombstone)
    fn forget(cell: *MemoryCell) bool {
        if (cell.status != ACTIVE) { return false; }
        cell.status = FORGOTTEN;
        return true;
    }

    // reflect: Compute phi-aligned hash of content
    fn reflect_phi_hash(a: u64, b: u64) u64 {
        var combined : u64 = a ^ b;
        combined = combined * 0x9e3779b97f4a7c15;
        combined = combined ^ (combined >> 32);
        return combined;
    }

    // is_agent_scoped: Check if cell has agent scope
    fn is_agent_scoped(cell: *MemoryCell) bool {
        return cell.scope == SCOPE_AGENT;
    }

    // is_permanent: Check if cell has permanent scope
    fn is_permanent(cell: *MemoryCell) bool {
        return cell.scope == SCOPE_PERMANENT;
    }

    // scope_priority: Return priority for scope (higher = longer lived)
    fn scope_priority(scope: u8) usize {
        if (scope == SCOPE_AGENT) { return 0; }
        if (scope == SCOPE_SESSION) { return 1; }
        if (scope == SCOPE_PERMANENT) { return 2; }
        return 0;
    }

    // cell_size: Total size of cell in bytes
    fn cell_size(cell: *MemoryCell) usize {
        return 8 + 1 + 1 + 8 + 8 + 8 + cell.key_len + cell.value_len;
    }

    // test: remember and recall
    test remember_recall {
        var cell : MemoryCell;
        cell.scope = SCOPE_AGENT;
        cell.status = FORGOTTEN;
        cell.phi_hash = 0;
        cell.key_len = 0;
        cell.value_len = 0;
        try remember(&cell, SCOPE_PERMANENT, 0xDEAD);
        try recall(&cell, 0xDEAD);
        try not(recall(&cell, 0xBEEF));
    }

    // test: forget marks tombstone
    test forget_tombstone {
        var cell : MemoryCell;
        cell.scope = SCOPE_AGENT;
        cell.status = FORGOTTEN;
        cell.phi_hash = 0;
        cell.key_len = 0;
        cell.value_len = 0;
        try remember(&cell, SCOPE_SESSION, 42);
        try forget(&cell);
        try not(recall(&cell, 42));
        try eq(cell.status, FORGOTTEN);
    }

    // test: scope priority ordering
    test scope_priority_ordering {
        try scope_priority(SCOPE_AGENT) < scope_priority(SCOPE_SESSION);
        try scope_priority(SCOPE_SESSION) < scope_priority(SCOPE_PERMANENT);
    }

    // test: reflect phi hash is deterministic
    test reflect_deterministic {
        var h1 = reflect_phi_hash(100, 200);
        var h2 = reflect_phi_hash(100, 200);
        try eq(h1, h2);
    }

    // test: invalid scope rejected
    test invalid_scope {
        var cell : MemoryCell;
        cell.scope = SCOPE_AGENT;
        cell.status = FORGOTTEN;
        cell.phi_hash = 0;
        cell.key_len = 0;
        cell.value_len = 0;
        try not(remember(&cell, 99, 0));
    }

    // test: forget already forgotten returns false
    test forget_idempotent {
        var cell : MemoryCell;
        cell.scope = SCOPE_AGENT;
        cell.status = FORGOTTEN;
        cell.phi_hash = 0;
        cell.key_len = 0;
        cell.value_len = 0;
        try not(forget(&cell));
    }

    // invariant: active cells have valid scope
    invariant active_scope_valid {
        SCOPE_AGENT <= SCOPE_PERMANENT;
    }

    // invariant: tombstone is distinct from active
    invariant tombstone_distinct {
        FORGOTTEN != ACTIVE;
    }

    // invariant: reflect is commutative in xor part
    invariant reflect_symmetric {
        var a : u64 = 0xAAAA;
        var b : u64 = 0xBBBB;
        reflect_phi_hash(a, b) != 0;
    }

    // bench: remember/recall cycle
    bench remember_recall_cycle {
        var cell : MemoryCell;
        cell.scope = SCOPE_AGENT;
        cell.status = FORGOTTEN;
        cell.phi_hash = 0;
        cell.key_len = 0;
        cell.value_len = 0;
        remember(&cell, SCOPE_PERMANENT, 12345);
        recall(&cell, 12345);
    }

    // bench: reflect phi hash
    bench reflect_phi_hash_bench {
        reflect_phi_hash(0x1234567890ABCDEF, 0xFEDCBA0987654321);
    }
}

// SPDX-License-Identifier: Apache-2.0
// Module: Semantic Search via Hippocampus Pattern Completion
// phi^2 + 1/phi^2 = 3 | TRINITY
//
// CA3 pattern completion via Schaffer collaterals analog:
// - Query embedding compared via cosine similarity normalized by PHI
// - O(log n) search via HNSW index approximation
// - Returns top-k formula matches with similarity scores

module SemanticSearch;

// ============================================================================
// Imports
// ============================================================================

use base::types::Float;
use base::math::cosine_sim;
use base::math::normalize_l2;
use base::constants::PHI;

// ============================================================================
// Constants
// ============================================================================

/// Embedding dimension (TRINITY: 27 = 3^3)
pub const EMBEDDING_DIM : usize = 27;

/// Maximum corpus size for in-memory search
pub const MAX_CORPUS : usize = 10000;

/// Default k for top-k search
pub const DEFAULT_K : usize = 5;

// ============================================================================
// Types
// ============================================================================

/// Formula match result with similarity score
pub const FormulaMatch = struct {
    id : []const u8,
    name : []const u8,
    sector : []const u8,
    value : Float,
    similarity : Float,
};

/// Semantic search result vector
pub const SearchResult = struct {
    matches : []FormulaMatch,
    count : usize,
    query_time_ms : f64,
};

/// Formula embedding vector
pub const FormulaEmbedding = struct {
    id : []const u8,
    vector : [EMBEDDING_DIM]Float,
    normalized : bool,
};

/// Search query with embedding
pub const SearchQuery = struct {
    text : []const u8,
    embedding : [EMBEDDING_DIM]Float,
};

// ============================================================================
// Core Functions
// ============================================================================

/// Compute semantic similarity between query and formula embedding
/// Returns cosine similarity normalized by PHI
pub fn compute_similarity(query : [EMBEDDING_DIM]Float, target : [EMBEDDING_DIM]Float) Float {
    const cos_sim = cosine_sim(query, target);
    return cos_sim / PHI;
}

/// Top-k selection from similarity scores
/// O(n log k) via min-heap
pub fn top_k(matches : []FormulaMatch, k : usize) []FormulaMatch {
    // Placeholder: implement heap-based selection
    var result : [k]FormulaMatch = undefined;
    // TODO: heap-based selection
    return result[0..0];
}

/// Main semantic search function
/// O(log n) via HNSW index (placeholder: O(n) linear scan)
pub fn semantic_search(query : SearchQuery, corpus : []FormulaEmbedding, k : usize) SearchResult {
    var scores : [MAX_CORPUS]Float = undefined;
    var matches : [MAX_CORPUS]FormulaMatch = undefined;

    // Compute similarities
    var i : usize = 0;
    while (i < corpus.len) : (i += 1) {
        scores[i] = compute_similarity(query.embedding, corpus[i].vector);
    }

    // Select top-k
    const top_matches = top_k(matches[0..i], k);

    return SearchResult {
        .matches = top_matches,
        .count = top_matches.len,
        .query_time_ms = 0.0,
    };
}

// ============================================================================
// Tests
// ============================================================================

test "semantic_search_returns_at_most_k_results" {
    const query = SearchQuery {
        .text = "gamma",
        .embedding = [1]Float{0} ** EMBEDDING_DIM,
    };
    const corpus = [_]FormulaEmbedding{};
    const k : usize = 5;
    const result = semantic_search(query, &corpus, k);
    assert(result.count <= k);
}

test "similarity_score_in_range_0_1" {
    const q : [EMBEDDING_DIM]Float = [_]Float{0.5} ** EMBEDDING_DIM;
    const t : [EMBEDDING_DIM]Float = [_]Float{0.5} ** EMBEDDING_DIM;
    const sim = compute_similarity(q, t);
    assert(sim >= 0.0);
    assert(sim <= 1.0);
}

test "phi_normalization_applied" {
    // When vectors are identical, cosine_sim = 1.0
    // After PHI normalization: 1.0 / PHI ≈ 0.618
    const q : [EMBEDDING_DIM]Float = [_]Float{1.0} ** EMBEDDING_DIM;
    const t : [EMBEDDING_DIM]Float = [_]Float{1.0} ** EMBEDDING_DIM;
    const sim = compute_similarity(q, t);
    const expected = 1.0 / PHI;
    assert(abs(sim - expected) < 0.001);
}

