    let mut targets: Vec<Hypervector> = Vec::new();

    for sample in 0..3 {
        let mut ctx: Context = [[TRIT_ZERO; DEFAULT_DIM]; CONTEXT_SIZE];
        for i in 0..CONTEXT_SIZE {
            for j in 0..100 {
                ctx[i][j] = ((sample + i + j) % 3) as i8 - 1;
            }
        }
        contexts.push(ctx);

        let mut tgt: Hypervector = [TRIT_ZERO; DEFAULT_DIM];
        for j in 0..100 {
            tgt[j] = ((sample + j) % 3) as i8 - 1;
        }
        targets.push(tgt);
    }

    let roles = init_roles(1024, 12345);
    let acc = compute_accuracy(&contexts, &targets, &roles, 1024, 0.9);

    // Accuracy should be in [0, 1]
    assert!(acc >= 0.0 && acc <= 1.0);
}

test "summarize_context_order_sensitive" {
    let mut ctx1: Context = [[TRIT_ZERO; DEFAULT_DIM]; CONTEXT_SIZE];
    let mut ctx2: Context = [[TRIT_ZERO; DEFAULT_DIM]; CONTEXT_SIZE];

    for i in 0..CONTEXT_SIZE {
        for j in 0..100 {
            ctx1[i][j] = (i as i8) - 1;
            ctx2[i][j] = ((CONTEXT_SIZE - 1 - i) as i8) - 1;
        }
    }

    let sum1 = summarize_context(&ctx1, 1024);
    let sum2 = summarize_context(&ctx2, 1024);

    // Different orders should produce different summaries
    let mut same = true;
    for i in 0..100 {
        if sum1[i] != sum2[i] {
            same = false;
            break;
        }
    }
    assert!(!same);
}

