    // TDD - Tests
    // ========================================================================

    test "vm_create_has_zero_registers"
        given vm = vm_create()
        then vm.registers.v0.data.get_dimension() == 0

    test "vm_create_pc_is_zero"
        given vm = vm_create()
        then vm.registers.pc == 0

    test "vm_create_not_halted"
        given vm = vm_create()
        then vm.halted == false

    test "vm_halt_sets_halted"
        given vm = vm_create()
        when halted = vm_halt(vm)
        then halted.halted == true

    test "vm_step_nop_increments_cycle"
        given vm = vm_create()
        and inst = VSAInstruction{ .opcode = .nop }
        when result = vm_step(vm, inst)
        then result.cycle_count == 1

    test "vm_step_halt_halts"
        given vm = vm_create()
        and inst = VSAInstruction{ .opcode = .halt }
        when result = vm_step(vm, inst)
        then result.halted == true

    test "vm_step_mov_copies_register"
        given vm = vm_create()
        and src = hybrid_arithmetic::create_unpacked([_]i8{ 1, 0 }, 2)
        and vm_with_src = vm_set_vreg(vm, 0, src)
        and inst = VSAInstruction{ .opcode = .v_mov, .src1 = 0, .dst = 1 }
        when result = vm_step(vm_with_src, inst)
        then result.registers.v1.data == src.data

    test "vm_step_add_adds_vectors"
        given a = hybrid_arithmetic::create_unpacked([_]i8{ 1 }, 1)
        and b = hybrid_arithmetic::create_unpacked([_]i8{ 1 }, 1)
        and vm_with_a = vm_set_vreg(vm_create(), 0, a)
        and vm_with_b = vm_set_vreg(vm_with_a, 1, b)
        and inst = VSAInstruction{ .opcode = .v_add, .src1 = 0, .src2 = 1, .dst = 2 }
        when result = vm_step(vm_with_b, inst)
        then result.registers.v2.data.get_dimension() > 0

    test "vm_step_neg_flips_sign"
        given a = hybrid_arithmetic::create_unpacked([_]i8{ 1 }, 1)
        and vm_with_a = vm_set_vreg(vm_create(), 0, a)
        and inst = VSAInstruction{ .opcode = v_neg, .src1 = 0, .dst = 1 }
        when result = vm_step(vm_with_a, inst)
        then result.registers.v1.data.get(0) == .neg

    test "vm_step_dot_product_stores_result"
        given a = hybrid_arithmetic::create_unpacked([_]i8{ 1 }, 1)
        and b = hybrid_arithmetic::create_unpacked([_]i8{ 1 }, 1)
        and vm_with_a = vm_set_vreg(vm_create(), 0, a)
        and vm_with_b = vm_set_vreg(vm_with_a, 1, b)
        and inst = VSAInstruction{ .opcode = .v_dot, .src1 = 0, .src2 = 1 }
        when result = vm_step(vm_with_b, inst)
        then result.registers.s0 > 0

    test "vm_get_vreg_0_returns_v0"
        given vm = vm_create()
        when result = vm_get_vreg(vm, 0)
        then result.data == vm.registers.v0.data

    test "vm_get_vreg_1_returns_v1"
        given vm = vm_create()
        when result = vm_get_vreg(vm, 1)
        then result.data == vm.registers.v1.data

    test "vm_get_vreg_invalid_returns_zero"
        given vm = vm_create()
        when result = vm_get_vreg(vm, 5)
        then result.data.get_dimension() == 0

    test "vm_set_vreg_0_sets_v0"
        given vm = vm_create()
        and vec = hybrid_arithmetic::create_unpacked([_]i8{ 1 }, 1)
        when result = vm_set_vreg(vm, 0, vec)
        then result.registers.v0.data == vec.data

    test "vm_set_vreg_1_sets_v1"
        given vm = vm_create()
        and vec = hybrid_arithmetic::create_unpacked([_]i8{ 1 }, 1)
        when result = vm_set_vreg(vm, 1, vec)
        then result.registers.v1.data == vec.data

    test "vm_step_permute_shifts"
        given a = hybrid_arithmetic::create_unpacked([_]i8{ 0, 1, 0 }, 3)
        and vm_with_a = vm_set_vreg(vm_create(), 0, a)
        and inst = VSAInstruction{ .opcode = .v_permute, .src1 = 0, .imm = 1, .dst = 1 }
        when result = vm_step(vm_with_a, inst)
        then result.cycle_count == 1

    test "vm_step_ipermute_shifts_back"
        given a = hybrid_arithmetic::create_unpacked([_]i8{ 0, 1, 0 }, 3)
        and vm_with_a = vm_set_vreg(vm_create(), 0, a)
        and inst = VSAInstruction{ .opcode = .v_ipermute, .src1 = 0, .imm = 1, .dst = 1 }
        when result = vm_step(vm_with_a, inst)
        then result.cycle_count == 1

    test "vm_step_bind_associates"
        given a = hybrid_arithmetic::create_unpacked([_]i8{ 1 }, 1)
        and b = hybrid_arithmetic::create_unpacked([_]i8{ 0 }, 1)
        and vm_with_a = vm_set_vreg(vm_set_vreg(vm_create(), 0, a), 1, b)
        and inst = VSAInstruction{ .opcode = .v_bind, .src1 = 0, .src2 = 1, .dst = 2 }
        when result = vm_step(vm_with_a, inst)
        then result.cycle_count == 1

    test "vm_step_unbind_reverses_bind"
        given a = hybrid_arithmetic::create_unpacked([_]i8{ 1 }, 1)
        and b = hybrid_arithmetic::create_unpacked([_]i8{ 0 }, 1)
        and vm_with_a = vm_set_vreg(vm_set_vreg(vm_create(), 0, a), 1, b)
        and bind_inst = VSAInstruction{ .opcode = .v_bind, .src1 = 0, .src2 = 1, .dst = 2 }
        and bound = vm_step(vm_with_a, bind_inst)
        and unbind_inst = VSAInstruction{ .opcode = .v_unbind, .src1 = 2, .src2 = 1, .dst = 3 }
        when result = vm_step(bound, unbind_inst)
        then result.cycle_count == 2

    test "vm_step_bundle2_combines"
        given a = hybrid_arithmetic::create_unpacked([_]i8{ 1 }, 1)
        and b = hybrid_arithmetic::create_unpacked([_]i8{ 0 }, 1)
        and vm_with_a = vm_set_vreg(vm_set_vreg(vm_create(), 0, a), 1, b)
        and inst = VSAInstruction{ .opcode = .v_bundle2, .src1 = 0, .src2 = 1, .dst = 2 }
        when result = vm_step(vm_with_a, inst)
        then result.cycle_count == 1

    // ========================================================================
    // TDD - Invariants
    // ========================================================================

    invariant vm_step_preserves_cycle_count
        // Each step increments cycle_count by 1
        const vm = vm_create();
        const inst = VSAInstruction{ .opcode = .nop };
        const result = vm_step(vm, inst);
        assert result.cycle_count == vm.cycle_count + 1;

    invariant vm_halt_sets_halted_flag
        // Halt instruction sets halted flag
        const vm = vm_create();
        const inst = VSAInstruction{ .opcode = .halt };
        const result = vm_halt(vm);
        assert result.halted == true;

    invariant vm_halt_prevents_execution
        // Halted VM doesn't execute instructions
        const vm = vm_create();
        const inst = VSAInstruction{ .opcode = .nop };
        const halted = vm_halt(vm);
        const result = vm_step(halted, inst);
        assert result.halted == true;

    invariant vm_registers_initialized_to_zero
        // All registers initialized to zero
        const vm = vm_create();
        assert vm.registers.v0.data.get_dimension() == 0;
        assert vm.registers.v1.data.get_dimension() == 0;
        assert vm.registers.v2.data.get_dimension() == 0;
        assert vm.registers.v3.data.get_dimension() == 0;
        assert vm.registers.s0 == 0;
        assert vm.registers.s1 == 0;

    invariant vm_get_vreg_valid_range
        // Valid register indices return valid registers
        const vm = vm_create();
        const r0 = vm_get_vreg(vm, 0);
        const r1 = vm_get_vreg(vm, 1);
        const r2 = vm_get_vreg(vm, 2);
        const r3 = vm_get_vreg(vm, 3);
        assert r0.data == vm.registers.v0.data;
        assert r1.data == vm.registers.v1.data;
        assert r2.data == vm.registers.v2.data;
        assert r3.data == vm.registers.v3.data;

    invariant vm_get_vreg_invalid_returns_zero
        // Invalid register index returns zero vector
        const vm = vm_create();
        const r_invalid = vm_get_vreg(vm, 5);
        assert r_invalid.data.get_dimension() == 0;

    // ========================================================================
    // TDD - Benchmarks
    // ========================================================================

    bench "vm_create_latency"
        // Measure: cycles for VM creation
        // Target: < 100 cycles
        @setEvalBranchQuota(10000);
        var result : VSAVM = undefined;
        for (0..1000) |_| {
            result = vm_create();
        }
        _ = result;

    bench "vm_step_nop_latency"
        // Measure: cycles for NOP instruction
        // Target: < 10 cycles
        @setEvalBranchQuota(10000);
        const vm = vm_create();
        const inst = VSAInstruction{ .opcode = .nop };
        var result : VSAVM = undefined;
        for (0..1000) |_| {
            result = vm_step(vm, inst);
        }
        _ = result;

    bench "vm_step_mov_latency"
        // Measure: cycles for MOV instruction
        // Target: < 50 cycles
        @setEvalBranchQuota(10000);
        const vm = vm_create();
        const inst = VSAInstruction{ .opcode = .v_mov, .src1 = 0, .dst = 1 };
        var result : VSAVM = undefined;
        for (0..1000) |_| {
            result = vm_step(vm, inst);
        }
        _ = result;

    bench "vm_step_add_latency"
        // Measure: cycles for ADD instruction
        // Target: < 200 cycles (vector addition)
        @setEvalBranchQuota(10000);
        const vm = vm_create();
        const inst = VSAInstruction{ .opcode = .v_add, .src1 = 0, .src2 = 1, .dst = 2 };
        var result : VSAVM = undefined;
        for (0..1000) |_| {
            result = vm_step(vm, inst);
        }
        _ = result;

    bench "vm_step_dot_latency"
        // Measure: cycles for DOT instruction
        // Target: < 200 cycles (dot product)
        @setEvalBranchQuota(10000);
        const vm = vm_create();
        const inst = VSAInstruction{ .opcode = .v_dot, .src1 = 0, .src2 = 1 };
        var result : VSAVM = undefined;
        for (0..1000) |_| {
            result = vm_step(vm, inst);
        }
        _ = result;

    bench "vm_step_bind_latency"
        // Measure: cycles for BIND instruction
        // Target: < 200 cycles
        @setEvalBranchQuota(10000);
        const vm = vm_create();
        const inst = VSAInstruction{ .opcode = .v_bind, .src1 = 0, .src2 = 1, .dst = 2 };
        var result : VSAVM = undefined;
        for (0..1000) |_| {
            result = vm_step(vm, inst);
        }
        _ = result;
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/partition.t27
// T27 Multi-FPGA Partition Specification
// Automatically partitions HIR modules across multiple FPGAs
// Estimates inter-FPGA bandwidth and latency
// Uses flat arrays + count fields (parser-compatible)
// phi^2 + 1/phi^2 = 3 | TRINITY

module Partition {

    // === FPGA node ===

    pub struct FpgaNode {
        name : &str,
        device : &str,
        luts : u32,
        ffs : u32,
        bram18 : u32,
        dsp48 : u32,
        io_pins : u32,
    }

    fn fpga_node(name: &str, device: &str, luts: u32, ffs: u32, bram18: u32, dsp48: u32, io: u32) -> FpgaNode {
        return FpgaNode{
            .name = name,
            .device = device,
            .luts = luts,
            .ffs = ffs,
            .bram18 = bram18,
            .dsp48 = dsp48,
            .io_pins = io,
        };
    }

    fn arty_a7_node(name: &str) -> FpgaNode {
        return fpga_node(name, "xc7a100t", 63400, 126800, 135, 240, 300);
    }

    // === Inter-FPGA link ===

    pub struct InterFpgaLink {
        fpga_a : u32,
        fpga_b : u32,
        width : u32,
        protocol : i8,
        max_mbps : u32,
    }

    fn lvds_link(a: u32, b: u32, width: u32) -> InterFpgaLink {
        return InterFpgaLink{
            .fpga_a = a,
            .fpga_b = b,
            .width = width,
            .protocol = 0,
            .max_mbps = 1000,
        };
    }

    fn serdes_link(a: u32, b: u32) -> InterFpgaLink {
        return InterFpgaLink{
            .fpga_a = a,
            .fpga_b = b,
            .width = 4,
            .protocol = 1,
            .max_mbps = 6250,
        };
    }

    fn link_bandwidth_mbps(link: InterFpgaLink) -> u32 {
        return link.width * link.max_mbps;
    }

    // === Partition assignment ===

    pub struct PartitionAssign {
        module_name : &str,
        fpga_idx : u32,
        luts : u32,
        ffs : u32,
        bram18 : u32,
        dsp48 : u32,
    }

    // NB: the parameter is `mod_name`, not `module`. `module` is the keyword
    // that opens a declaration, and a parameter carrying that name aborts the
    // body parse -- silently, taking every declaration after it, tests
    // included, out of the emitted module.
    fn assignment(mod_name: &str, fpga: u32, luts: u32, ffs: u32, bram: u32, dsp: u32) -> PartitionAssign {
        return PartitionAssign{
            .module_name = mod_name,
            .fpga_idx = fpga,
            .luts = luts,
            .ffs = ffs,
            .bram18 = bram,
            .dsp48 = dsp,
        };
    }

    // === Partition result ===

    pub struct PartitionResult {
        num_fpgas : u32,
        num_assignments : u32,
        num_links : u32,
        total_bandwidth_mbps : u32,
        balanced : bool,
        errors : u32,
    }

    fn partition_ok(fpgas: u32, assigns: u32, links: u32, bw: u32) -> PartitionResult {
        return PartitionResult{
            .num_fpgas = fpgas,
            .num_assignments = assigns,
            .num_links = links,
            .total_bandwidth_mbps = bw,
            .balanced = true,
            .errors = 0,
        };
    }

    fn partition_fail(errors: u32) -> PartitionResult {
        return PartitionResult{
            .num_fpgas = 0,
            .num_assignments = 0,
            .num_links = 0,
            .total_bandwidth_mbps = 0,
            .balanced = false,
            .errors = errors,
        };
    }

    fn passed(r: PartitionResult) -> bool {
        return r.errors == 0;
    }

    // === Query ===

    // Read-only over the array, so the parameter is const: `[InterFpgaLink]`
    // emits a mutable slice, which no expression a test can write will coerce
    // to, and the test below could not be called at all.
    fn total_link_bandwidth(links: []const InterFpgaLink, count: u32) -> u32 {
        var total : u32 = 0;
        var i : u32 = 0;
        while i < count {
            total = total + link_bandwidth_mbps(links[i]);
            i = i + 1;
        }
        return total;
    }

    fn fpga_util(fpga: FpgaNode, used_luts: u32) -> u32 {
        if fpga.luts == 0 {
            return 0;
        }
        return used_luts * 100 / fpga.luts;
    }

    fn fpga_remaining(fpga: FpgaNode, used_luts: u32) -> u32 {
        if used_luts > fpga.luts {
            return 0;
        }
        return fpga.luts - used_luts;
    }

    // === Validation ===

    fn validate_node(n: FpgaNode) -> u32 {
        var errors : u32 = 0;
        if n.name == "" {
            errors = errors + 1;
        }
        if n.luts == 0 {
            errors = errors + 1;
        }
        return errors;
    }

    // === Tests ===

    test fpga_node_creation
        given n = arty_a7_node("fpga0")
        then n.name == "fpga0"
        and n.device == "xc7a100t"
        and n.luts == 63400

    test lvds_link_creation
        given l = lvds_link(0, 1, 8)
        then l.fpga_a == 0
        and l.fpga_b == 1
        and l.width == 8
        and link_bandwidth_mbps(l) == 8000

    test serdes_link_creation
        given l = serdes_link(0, 1)
        then l.protocol == 1
        and link_bandwidth_mbps(l) == 25000

    test assignment_creation
        given a = assignment("uart", 0, 200, 100, 1, 0)
        then a.module_name == "uart"
        and a.fpga_idx == 0

    test partition_ok_creation
        given r = partition_ok(2, 5, 1, 8000)
        then r.num_fpgas == 2
        and r.balanced == true
        and passed(r) == true

    test partition_fail_creation
        given r = partition_fail(1)
        then passed(r) == false

    test total_link_bandwidth
        then total_link_bandwidth(&[_]InterFpgaLink{lvds_link(0, 1, 8), lvds_link(1, 2, 4)}, 2) == 12000

    // count, not length, decides how much of the array is summed: the flat
    // array + count convention means a short count must ignore the tail.
    test total_link_bandwidth_respects_count
        then total_link_bandwidth(&[_]InterFpgaLink{lvds_link(0, 1, 8), lvds_link(1, 2, 4)}, 1) == 8000
        and total_link_bandwidth(&[_]InterFpgaLink{lvds_link(0, 1, 8), lvds_link(1, 2, 4)}, 0) == 0

    test fpga_util_calc
        given n = arty_a7_node("fpga0")
        then fpga_util(n, 31700) == 50

    test fpga_remaining_calc
        given n = arty_a7_node("fpga0")
        then fpga_remaining(n, 10000) == 53400

    test fpga_remaining_over
        given n = arty_a7_node("fpga0")
        then fpga_remaining(n, 100000) == 0

    test validate_node_ok
        given n = arty_a7_node("fpga0")
        then validate_node(n) == 0

    test validate_node_empty
        given n = FpgaNode{.name = "", .device = "xc7a100t", .luts = 0, .ffs = 0, .bram18 = 0, .dsp48 = 0, .io_pins = 0}
        then validate_node(n) > 0

    // Both faults are counted, not just the first one found.
    test validate_node_counts_every_fault
        given n = FpgaNode{.name = "", .device = "xc7a100t", .luts = 0, .ffs = 0, .bram18 = 0, .dsp48 = 0, .io_pins = 0}
        then validate_node(n) == 2

    // The three ends of the utilisation range.
    test fpga_util_endpoints
        given n = arty_a7_node("fpga0")
        then fpga_util(n, 0) == 0
        and fpga_util(n, 63400) == 100

    // A zero-LUT node would divide by zero; the guard returns 0 instead.
    test fpga_util_zero_lut_node
        given n = FpgaNode{.name = "empty", .device = "none", .luts = 0, .ffs = 0, .bram18 = 0, .dsp48 = 0, .io_pins = 0}
        then fpga_util(n, 1000) == 0

    // Exactly full is 0 remaining, not an underflow.
    test fpga_remaining_exact_fit
        given n = arty_a7_node("fpga0")
        then fpga_remaining(n, 63400) == 0
        and fpga_remaining(n, 0) == 63400

    // used + remaining == capacity, for any load within capacity.
    test fpga_remaining_complements_use
        given n = arty_a7_node("fpga0")
        then fpga_remaining(n, 20000) + 20000 == n.luts

    // partition_fail carries the error count through and never reports passed.
    test partition_fail_carries_count
        given r = partition_fail(3)
        then r.errors == 3
        and r.balanced == false
        and r.num_fpgas == 0
        and passed(r) == false

    // SERDES is 4 lanes at 6250 Mbps; the protocol tag separates it from LVDS.
    test serdes_link_shape
        given s = serdes_link(2, 3)
        and l = lvds_link(2, 3, 4)
        then s.width == 4
        and s.fpga_a == 2
        and s.fpga_b == 3
        and s.protocol != l.protocol

    // === Invariants ===

    invariant bandwidth_non_negative
        given l = lvds_link(0, 1, 8)
        assert link_bandwidth_mbps(l) >= 0

    invariant util_bounded
        given n = arty_a7_node("inv")
        assert fpga_util(n, 0) == 0

    bench fpga_util_latency
        measure: nanoseconds to fpga_util(arty_a7_node("bench"), 15850)
        target: < 50ns

    bench link_bandwidth_latency
        measure: nanoseconds to link_bandwidth_mbps(lvds_link(0, 1, 8))
        target: < 50ns
}

// phi^2 + 1/phi^2 = 3 | TRINITY

// SPDX-License-Identifier: Apache-2.0
; 01 — Values and types
; Lesson 1 of the t27 tutorial. Every constant carries an explicit width,
; because a spec has to say what reaches hardware rather than let a compiler
; pick for it. Nothing here is inferred.
; phi^2 + 1/phi^2 = 3 | TRINITY

module tutorial-01-values;

// ============================================================================
// Integers
//
// Width and signedness are part of the name's type, always written out.
// u = unsigned, i = signed, and the number is the bit width.
// ============================================================================

pub const SMALL_UNSIGNED : u8 = 200;
pub const SMALL_SIGNED : i8 = -100;
pub const WIDE_UNSIGNED : u16 = 65535;
pub const WIDER : u32 = 4000000000;
pub const SIGNED_32 : i32 = -2000000;

// ============================================================================
// Other bases
//
// Hex and binary are ordinary integer literals. Binary is worth using wherever
// the value IS a bit pattern -- a mask written as 0b111111111 documents its own
// width in a way that 511 does not.
// ============================================================================

pub const AS_HEX : u16 = 0xFFFF;
pub const AS_BINARY : u8 = 0b1010;
pub const MANTISSA_MASK : u16 = 0b111111111;

// ============================================================================
// Floats and booleans
// ============================================================================

pub const RATIO : f32 = 1.5;
pub const PRECISE : f64 = 2.25;

pub const ENABLED : bool = true;
pub const DISABLED : bool = false;

// ============================================================================
// The trit
//
// This language is built on three states rather than two. A trit is stored in
// an i8 and is only ever -1, 0 or +1; the invariant at the bottom is what
// makes that a claim rather than a comment.
// ============================================================================

pub const TRIT_NEG : i8 = -1;
pub const TRIT_ZERO : i8 = 0;
pub const TRIT_POS : i8 = 1;

pub const TRINITY : i8 = 3;

// ============================================================================
// Invariants
//
// An invariant states something that must hold for the module as a whole. It
// is checked, not decorative.
// ============================================================================

invariant trit_range_is_three_states
    assert TRIT_POS - TRIT_NEG + 1 == TRINITY

invariant masks_match_their_widths
    assert MANTISSA_MASK == 511

